  const vals = SRC.map((s) => cur[s.k][i]), tot = vals.reduce((a, b) => a + b, 0), sh = shares(vals, tot);
  const order = SRC.map((s, j) => ({ s, v: vals[j], p: sh[j] })).sort((a, b) => b.v - a.v);
  const key = order.map((o) => o.s.k).join();
  if (mixList.dataset.key !== key) {
    mixList.dataset.key = key;
    mixList.innerHTML = order.map((o, j) => `<li class="dbt-grid-mixrow" data-k="${o.s.k}" style="--i:${j};--c:${COLOR(o.s.k)}"><span><i></i>${o.s.name}</span><b data-v></b><div class="dbt-grid-bar"><i></i></div></li>`).join('');
  }
  order.forEach((o) => {
    const li = $(`[data-k="${o.s.k}"]`, mixList);
    $('[data-v]', li).innerHTML = `${nf0.format(o.v)} MW<small>${nf1.format(o.p)}%</small>`;
    $('.dbt-grid-bar i', li).style.setProperty('--s', (o.p / 100).toFixed(4));
    li.toggleAttribute('data-off', st.off.has(o.s.k));
  });
  $('[data-mixat]').textContent = when(i) + (cur.agg > 1 ? ' mean' : '');
  $('[data-m="dem"]').textContent = nf0.format(tot) + ' MW';
  $('[data-m="net"]').textContent = nf0.format(cur.net[i]) + ' MW';
  const err = ((cur.fc[i] - tot) / tot) * 100;
  $('[data-m="err"]').textContent = (err >= 0 ? '+' : '−') + nf1.format(Math.abs(err)) + '%';
  $('[data-m="curt"]').textContent = nf0.format(cur.curt[i]) + ' MW';
  const ci = cur.ci[i];
  $('[data-m="ci"]').textContent = nf0.format(ci) + ' g/kWh';
  $('.dbt-grid-cigm').style.setProperty('--x', clamp(ci / 300, 0, 1).toFixed(4));
  $('.dbt-grid-cig').dataset.band = ci < 100 ? 'lo' : ci < 200 ? 'mid' : 'hi';
}

/* ---------- legend ---------- */
const legend = $('.dbt-grid-legend');
legend.innerHTML = SRC.slice().reverse().map((s) => `<button class="dbt-grid-lg" data-k="${s.k}" aria-pressed="true" style="--c:${COLOR(s.k)}"><i></i>${s.name}</button>`).join('');
legend.addEventListener('click', (e) => {
  const b = e.target.closest('.dbt-grid-lg'); if (!b) return;
  const k = b.dataset.k;
  if (st.off.has(k)) st.off.delete(k);
  else { if (st.off.size >= SRC.length - 1) return; st.off.add(k); }
  b.setAttribute('aria-pressed', String(!st.off.has(k)));
  retarget(false);
  renderMix(st.cursor);
});

/* ---------- KPIs (count-up) ---------- */
function count(el, to, dec) {
  const from = parseFloat(el.dataset.v || '0'); el.dataset.v = to;
  const fmt = (v) => (dec ? nf1.format(v) : nf0.format(v));
  if (reduce) { el.textContent = fmt(to); return; }
  const t0 = performance.now();
  const tick = (now) => {
    if (!root.isConnected) return;
    const k = clamp((now - t0) / 700, 0, 1);
    el.textContent = fmt(from + (to - from) * easeOut(k));
    if (k < 1) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}
function renderKpis() {
  const T = cur.tot, ren = SRC.filter((s) => s.ren).reduce((a, s) => a + T[s.k], 0);
  count($('[data-k="peak"]'), T.peak, 0);
  $('[data-k="peakAt"]').textContent = `${dayLbl(T.peakAt)} · ${hh(T.peakAt)}`;
  count($('[data-k="energy"]'), T.demand / 1000, 1);
  $('[data-k="energyNote"]').textContent = `avg ${nf0.format(T.demand / cur.hours)} MW`;
  count($('[data-k="ren"]'), (ren / T.demand) * 100, 1);
  $('[data-k="renNote"]').textContent = `${nf0.format(ren)} MWh hydro·wind·solar`;
  count($('[data-k="ci"]'), (T.em * 1000) / T.demand, 0);
  $('[data-k="ciNote"]').textContent = `${nf0.format(T.em)} t CO₂`;
  $('[data-span]').textContent = RANGES[cur.key].span;
}

/* ---------- carbon view ---------- */
const cplot = $('.dbt-grid-cplot'), csvg = $('.dbt-grid-csvg'), ctip = $('.dbt-grid-tip', cplot);
let cg = null;
function drawCarbon(animate) {
  const w = cplot.clientWidth, h = cplot.clientHeight; if (!w || !h) return;
  csvg.setAttribute('viewBox', `0 0 ${w} ${h}`);
  const L = 40, R = 12, T = 12, B = 24, pw = w - L - R, ph = h - T - B, n = cur.n;
  const ymax = Math.max(300, Math.ceil((Math.max(...cur.ci) * 1.1) / 50) * 50);
  const X = (i) => L + (i / Math.max(1, n - 1)) * pw, Y = (v) => T + ph - (v / ymax) * ph;
  cg = { X, Y, L, pw, T, ph, h };
  const xs = cur.ci.map((_, i) => X(i)), ys = cur.ci.map(Y);
  const off = (v) => clamp(1 - (Y(v) - T) / ph, 0, 1).toFixed(4);
  let s = `<defs><linearGradient id="dbt-grid-cig" gradientUnits="userSpaceOnUse" x1="0" y1="${T + ph}" x2="0" y2="${T}">
    <stop offset="0" stop-color="var(--dbt-grid-ci-lo)"/><stop offset="${off(100)}" stop-color="var(--dbt-grid-ci-lo)"/><stop offset="${off(100)}" stop-color="var(--dbt-grid-ci-mid)"/>
    <stop offset="${off(200)}" stop-color="var(--dbt-grid-ci-mid)"/><stop offset="${off(200)}" stop-color="var(--dbt-grid-ci-hi)"/><stop offset="1" stop-color="var(--dbt-grid-ci-hi)"/></linearGradient></defs><g class="dbt-grid-cgy">`;
  for (let v = 0; v <= ymax; v += 50) s += `<line x1="${L}" x2="${w - R}" y1="${Y(v)}" y2="${Y(v)}"/>${v % 100 === 0 ? `<text x="${L - 8}" y="${Y(v) + 3.5}" text-anchor="end">${v}</text>` : ''}`;
  s += `</g>`;
  [100, 200].forEach((v) => { s += `<line class="dbt-grid-thr" x1="${L}" x2="${w - R}" y1="${Y(v)}" y2="${Y(v)}"/>`; });
  for (let i = 0; i < n; i++) {
    const hr = cur.start[i], hour = dt(hr).getUTCHours(), date = dt(hr).getUTCDate();
    let lbl = '';
    if (cur.key === '24h' && i % (pw < 420 ? 6 : 3) === 0) lbl = hh(hr);
    else if (cur.key === '7d' && hour === 0 && (pw > 420 || dt(hr).getUTCDay() % 2)) lbl = `${WD[dt(hr).getUTCDay()]} ${date}`;
    else if (cur.key === '30d' && hour === 0 && (date === 1 || date % (pw < 420 ? 10 : 5) === 0)) lbl = `${date} Sep`;
    if (lbl) s += `<text x="${X(i)}" y="${h - 6}" text-anchor="${i === 0 ? 'start' : 'middle'}">${lbl}</text>`;
  }
  const top = `M${xs[0]},${ys[0]}${curve(xs, ys)}`;
  s += `<path class="dbt-grid-ciarea" fill="url(#dbt-grid-cig)" d="${top}L${xs[n - 1]},${T + ph}L${xs[0]},${T + ph}Z"/><path class="dbt-grid-ciline" stroke="url(#dbt-grid-cig)" pathLength="1" d="${top}"/>`;
  s += `<text x="${L - 8}" y="9" text-anchor="end">g/kWh</text><g class="dbt-grid-cross"><line/><circle class="dbt-grid-cc" r="4"/></g>`;
  csvg.innerHTML = s;
  if (animate && !reduce) {
    const ln = $('.dbt-grid-ciline', csvg);
    ln.style.strokeDasharray = '1';
    ln.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], { duration: 1100, easing: 'cubic-bezier(.3,.7,.2,1)', fill: 'both' });
    $('.dbt-grid-ciarea', csvg).animate([{ opacity: 0 }, { opacity: 0.22 }], { duration: 900, delay: 300, easing: 'ease-out', fill: 'both' });
  }
  if (st.ccursor >= 0) placeC(st.ccursor);
}
function placeC(i) {
  if (!cg) return;
  st.ccursor = clamp(i, 0, cur.n - 1); i = st.ccursor;
  const x = cg.X(i), y = cg.Y(cur.ci[i]), g = $('.dbt-grid-cross', csvg);
  const ln = $('line', g); ln.setAttribute('x1', x); ln.setAttribute('x2', x); ln.setAttribute('y1', cg.T); ln.setAttribute('y2', cg.T + cg.ph);
  const c = $('circle', g); c.setAttribute('cx', x); c.setAttribute('cy', y);
  g.setAttribute('data-on', '');
  const band = cur.ci[i] < 100 ? 'low' : cur.ci[i] < 200 ? 'moderate' : 'high';
  ctip.innerHTML = `<h4>${when(i)}</h4><ul><li><i style="background:none"></i><span>Intensity</span><b>${nf0.format(cur.ci[i])} g/kWh</b></li><li><i style="--c:var(--dbt-grid-gas)"></i><span>Gas</span><b>${nf0.format(cur.gas[i])} MW</b></li><li><i style="--c:var(--dbt-grid-imports)"></i><span>Imports</span><b>${nf0.format(cur.imports[i])} MW</b></li><li><i style="background:none"></i><span>Band</span><b>${band}</b></li></ul>`;
  const w = cplot.clientWidth, tw = ctip.offsetWidth, th = ctip.offsetHeight, right = x + 14 + tw > w;
  ctip.style.setProperty('--ox', right ? 'right' : 'left');
  ctip.style.translate = `${right ? x - 14 - tw : x + 14}px ${clamp(y - th - 8, 4, cg.h - th - 4)}px`;
  ctip.setAttribute('data-on', '');
}
function hideC() { st.ccursor = -1; const g = $('.dbt-grid-cross', csvg); if (g) g.removeAttribute('data-on'); ctip.removeAttribute('data-on'); }
cplot.addEventListener('pointermove', (e) => { if (!cg) return; const r = csvg.getBoundingClientRect(); placeC(Math.round(((e.clientX - r.left - cg.L) / cg.pw) * (cur.n - 1))); });
cplot.addEventListener('pointerleave', hideC);
cplot.addEventListener('blur', hideC);
cplot.addEventListener('keydown', (e) => {
  const c = st.ccursor < 0 ? cur.n - 1 : st.ccursor;
  const map = { ArrowLeft: c - 1, ArrowRight: c + 1, Home: 0, End: cur.n - 1 };
  if (e.key === 'Escape') { hideC(); return; }
  if (!(e.key in map)) return;
  e.preventDefault(); placeC(map[e.key]);
});
function renderEmissions() {
  const T = cur.tot;
  $('[data-etab]').innerHTML = SRC.slice().sort((a, b) => b.g * T[b.k] - a.g * T[a.k] || T[b.k] - T[a.k]).map((s) => {
    const t = (T[s.k] * s.g) / 1000;
    return `<tr><td><span style="--c:${COLOR(s.k)}"><i></i>${s.name}</span></td><td>${nf0.format(T[s.k])}</td><td class="${s.g ? '' : 'dbt-grid-dim'}">${s.g}</td><td class="${t ? '' : 'dbt-grid-dim'}">${nf0.format(t)}</td></tr>`;
  }).join('');
  $('[data-efoot]').innerHTML = `<tr><td>Total</td><td>${nf0.format(T.demand)}</td><td>${nf0.format((T.em * 1000) / T.demand)}</td><td>${nf0.format(T.em)}</td></tr>`;
}

/* ---------- sources table with FLIP reorder ---------- */
const stab = $('[data-stab]');
function srcRows() {
  const T = cur.tot, sh = shares(SRC.map((s) => T[s.k]), T.demand);
  return SRC.map((s, j) => ({ s, cap: s.cap, energy: T[s.k] / 1000, share: sh[j], cf: (T[s.k] / (s.cap * cur.hours)) * 100, peak: T[s.k + 'Peak'], curt: s.k === 'wind' ? T.curtW : s.k === 'solar' ? T.curtS : -1, name: s.name }));
}
function renderSources() {
  const rows = srcRows(), { k, dir } = st.sort;
  rows.sort((a, b) => (k === 'name' ? a.name.localeCompare(b.name) : a[k] - b[k]) * dir);
  const before = new Map($$('tr', stab).map((tr) => [tr.dataset.k, tr.getBoundingClientRect().top]));
  const html = rows.map((r) => `<tr data-k="${r.s.k}"><td><span style="--c:${COLOR(r.s.k)}"><i></i>${r.name}</span></td><td>${nf0.format(r.cap)}</td><td>${nf1.format(r.energy)}</td><td><span class="dbt-grid-share" style="--c:${COLOR(r.s.k)};--w:${r.share}%"><i></i>${nf1.format(r.share)}%</span></td><td><span class="dbt-grid-cf"><span class="dbt-grid-bullet" style="--c:${COLOR(r.s.k)};--a:${(r.cf / 100).toFixed(4)};--p:${(r.peak / r.cap).toFixed(4)}" title="average ${nf0.format(r.energy * 1000 / cur.hours)} MW · peak ${nf0.format(r.peak)} MW of ${nf0.format(r.cap)} MW"><i></i><b></b></span>${nf1.format(r.cf)}%</span></td><td>${nf0.format(r.peak)}</td><td class="${r.curt < 0 ? 'dbt-grid-dim' : ''}">${r.curt < 0 ? '—' : nf0.format(r.curt)}</td></tr>`).join('');
  stab.innerHTML = html;
  const T = cur.tot, capAll = SRC.reduce((a, x) => a + x.cap, 0), cAll = T.curtW + T.curtS;
  $('[data-sfoot]').innerHTML = `<tr><td>All sources</td><td>${nf0.format(capAll)}</td><td>${nf1.format(T.demand / 1000)}</td><td><span class="dbt-grid-share" style="--c:var(--dbt-grid-ink);--w:100%"><i></i>100.0%</span></td><td>${nf1.format((T.demand / (capAll * cur.hours)) * 100)}%</td><td>${nf0.format(T.peak)}</td><td>${nf0.format(cAll)}</td></tr>`;
  if (reduce || !before.size) return;
  $$('tr', stab).forEach((tr) => {
    const was = before.get(tr.dataset.k); if (was == null) return;
    const dy = was - tr.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) tr.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 460, easing: 'cubic-bezier(.2,.9,.25,1)' });
  });
}
$('.dbt-grid-stab thead').addEventListener('click', (e) => {
  const b = e.target.closest('[data-sort]'); if (!b) return;
  const k = b.dataset.sort;
  st.sort = { k, dir: st.sort.k === k ? -st.sort.dir : k === 'name' ? 1 : -1 };
  $$('.dbt-grid-stab th').forEach((th) => { const kk = $('button', th).dataset.sort; th.setAttribute('aria-sort', kk === k ? (st.sort.dir > 0 ? 'ascending' : 'descending') : 'none'); });
  renderSources();
});

/* ---------- views + range ---------- */
const TITLES = { balance: 'Supply & demand', carbon: 'Carbon intensity', sources: 'Source performance' };
const tabs = $$('.dbt-grid-navbtn');
function setView(v, focus) {
  st.view = v;
  tabs.forEach((b) => { const on = b.dataset.view === v; b.setAttribute('aria-selected', String(on)); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
  $$('.dbt-grid-view').forEach((s) => { s.hidden = s.dataset.view !== v; });
  $('[data-title]').textContent = TITLES[v];
  if (v === 'carbon') { renderEmissions(); requestAnimationFrame(() => drawCarbon(true)); }
  if (v === 'sources') { stab.innerHTML = ''; renderSources(); }
  if (v === 'balance') requestAnimationFrame(measure);
}
$('.dbt-grid-nav').addEventListener('click', (e) => { const b = e.target.closest('.dbt-grid-navbtn'); if (b && b.dataset.view !== st.view) setView(b.dataset.view); });
$('.dbt-grid-nav').addEventListener('keydown', (e) => {
  const i = tabs.findIndex((b) => b.dataset.view === st.view);
  const d = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key];
  if (e.key === 'Home' || e.key === 'End') { e.preventDefault(); setView(tabs[e.key === 'Home' ? 0 : tabs.length - 1].dataset.view, true); return; }
  if (!d) return;
  e.preventDefault(); setView(tabs[(i + d + tabs.length) % tabs.length].dataset.view, true);
});
const rbtns = $$('.dbt-grid-range button');
function setRange(r, focus) {
  if (r === st.range) return;
  st.range = r; cur = slice(r);
  rbtns.forEach((b) => { const on = b.dataset.range === r; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
  st.cursor = -1; cross.removeAttribute('data-on'); tip.removeAttribute('data-on');
  lastAxisKey = '';
  retarget(false);
  renderMix(cur.n - 1); renderKpis();
  if (st.view === 'carbon') { hideC(); renderEmissions(); drawCarbon(true); }
  if (st.view === 'sources') renderSources();
}
$('.dbt-grid-range').addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) setRange(b.dataset.range); });
$('.dbt-grid-range').addEventListener('keydown', (e) => {
  const d = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key]; if (!d) return;
  e.preventDefault();
  const i = rbtns.findIndex((b) => b.dataset.range === st.range);
  setRange(rbtns[(i + d + rbtns.length) % rbtns.length].dataset.range, true);
});

/* ---------- sizing ---------- */
function measure() {
  const w = plot.clientWidth, h = plot.clientHeight;
  if (!w || !h) return;
  if (w === W && h === Hh) return;
  W = w; Hh = h; svg.setAttribute('viewBox', `0 0 ${W} ${Hh}`); lastAxisKey = ''; draw();
}
let lastCW = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  measure();
  if (st.view === 'carbon' && cplot.clientWidth !== lastCW) { lastCW = cplot.clientWidth; drawCarbon(false); }
});
ro.observe(plot); ro.observe(cplot);

/* ---------- live frequency (pauses off screen and in hidden tabs) ---------- */
const fEl = $('[data-freq]'), fLine = $('.dbt-grid-fline'), fh = [];
let fv = 50, visible = false, timer = 0;
for (let i = 0; i < 40; i++) { fv = clamp(fv + (rnd() - 0.5) * 0.014 + (50 - fv) * 0.12, 49.94, 50.06); fh.push(fv); }
function paintFreq() {
  fEl.textContent = fv.toFixed(3);
  fEl.toggleAttribute('data-off', Math.abs(fv - 50) > 0.05);
  fLine.setAttribute('d', fh.map((v, i) => `${i ? 'L' : 'M'}${((i / (fh.length - 1)) * 100).toFixed(1)},${(11 - (v - 50) * 250).toFixed(2)}`).join(''));
}
function tick() {
  if (!root.isConnected) return;
  timer = 0;
  if (!visible || document.hidden) return;
  fv = clamp(fv + (Math.random() - 0.5) * 0.016 + (50 - fv) * 0.12, 49.94, 50.06);
  fh.push(fv); fh.shift(); paintFreq();
  timer = setTimeout(tick, 1600);
}
const wake = () => { if (!timer && visible && !document.hidden) timer = setTimeout(tick, 600); };
const onVis = () => { if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; } wake(); };
document.addEventListener('visibilitychange', onVis);
let entered = false;
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); document.removeEventListener('visibilitychange', onVis); return; }
  visible = entries[entries.length - 1].isIntersecting;
  if (visible && !entered) { entered = true; measure(); retarget(true); }
  wake();
});
io.observe(root);
$('[data-link]').textContent = nf0.format(D.imports[HOURS - 1]);
paintFreq();
renderKpis();
renderMix(cur.n - 1);
measure();

css:
@property --dbt-home-soc { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --dbt-home-ring { syntax: "<number>"; inherits: true; initial-value: 0; }
@keyframes dbt-home-pop { from { opacity: 0; scale: 0.6; } }
@keyframes dbt-home-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes dbt-home-grow { from { scale: 1 0; } }
@keyframes dbt-home-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbt-home-glow { 50% { box-shadow: 0 0 0 1px var(--c), 0 0 26px -4px var(--c); } }

.dbt-home {
  /* re-theme: background, ink, accent (solar) — the other flow hues derive their weight from these */
  --dbt-home-bg: oklch(0.19 0.012 70);
  --dbt-home-ink: oklch(0.95 0.014 85);
  --dbt-home-sun: oklch(0.83 0.15 78);
  --dbt-home-grid: oklch(0.74 0.055 245);
  --dbt-home-batt: oklch(0.8 0.15 150);
  --dbt-home-house: oklch(0.9 0.035 85);
  --dbt-home-ev: oklch(0.73 0.14 34);
  --dbt-home-panel: color-mix(in oklch, var(--dbt-home-bg), white 4%);
  --dbt-home-raise: color-mix(in oklch, var(--dbt-home-bg), white 8%);
  --dbt-home-deep: color-mix(in oklch, var(--dbt-home-bg), black 28%);
  --dbt-home-line: color-mix(in oklch, var(--dbt-home-ink) 9%, transparent);
  --dbt-home-line-2: color-mix(in oklch, var(--dbt-home-ink) 17%, transparent);
  --dbt-home-muted: color-mix(in oklch, var(--dbt-home-ink) 60%, var(--dbt-home-bg));
  --dbt-home-faint: color-mix(in oklch, var(--dbt-home-ink) 38%, var(--dbt-home-bg));
  --dbt-home-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dbt-home-spring: linear(0, 0.012, 0.05 2.6%, 0.19 5.6%, 0.79 14.4%, 0.98 18.6%, 1.06 22%, 1.08 25.4%, 1.05 30.6%, 1.006 38%, 0.993 45%, 1);
  --dbt-home-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbt-home-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background:
    radial-gradient(120% 70% at 30% -10%, color-mix(in oklch, var(--dbt-home-sun) 7%, transparent), transparent 60%),
    var(--dbt-home-bg);
  color: var(--dbt-home-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark;
  accent-color: var(--dbt-home-sun);
  box-shadow: inset 0 0 0 1px var(--dbt-home-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbt-home-sun); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ol, & ul { list-style: none; margin: 0; padding: 0; }
  & dl, & dd { margin: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbt-home-eyebrow { font: 600 10px/1.3 var(--dbt-home-mono); letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbt-home-muted); }

  .dbt-home-app { display: grid; height: 100%; grid-template-columns: 196px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side head" "side main"; }

  /* ---------- side ---------- */
  .dbt-home-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; background: var(--dbt-home-deep); border-right: 1px solid var(--dbt-home-line); }
  .dbt-home-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbt-home-brand svg { width: 32px; height: 32px; flex: none; padding: 5px; border-radius: 10px; background: var(--dbt-home-sun); fill: none; stroke: var(--dbt-home-bg); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dbt-home-brand span { display: grid; line-height: 1.2; min-width: 0; }
  .dbt-home-brand b { font-weight: 700; letter-spacing: -0.01em; }
  .dbt-home-brand small { font-size: 11px; color: var(--dbt-home-muted); white-space: nowrap; }
  .dbt-home-nav { display: grid; gap: 2px; }
  .dbt-home-navbtn {
    display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px 10px; border-radius: 9px; color: var(--dbt-home-muted); font-weight: 560;
    transition: color 160ms, background-color 160ms;
    & svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
    &:hover { color: var(--dbt-home-ink); background: color-mix(in oklch, var(--dbt-home-ink) 5%, transparent); }
    &[aria-selected="true"] { color: var(--dbt-home-ink); background: var(--dbt-home-raise); box-shadow: inset 0 0 0 1px var(--dbt-home-line); }
    &[aria-selected="true"] svg { color: var(--dbt-home-sun); }
  }
  .dbt-home-sys {
    margin-top: auto; display: grid; gap: 10px; padding: 14px 8px 0; border-top: 1px solid var(--dbt-home-line);
    & dt { font: 600 9.5px var(--dbt-home-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbt-home-faint); }
    & dd { font-size: 12px; color: var(--dbt-home-muted); }
  }

  /* ---------- head ---------- */
  .dbt-home-head { grid-area: head; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px 20px; padding: 18px 22px 14px; min-width: 0; }
  .dbt-home-titles { display: grid; gap: 4px; }
  .dbt-home-h { font-size: clamp(20px, 2.3cqi, 27px); font-weight: 650; letter-spacing: -0.025em; line-height: 1.05; }
  .dbt-home-days { display: flex; gap: 4px; padding: 3px; border-radius: 12px; background: var(--dbt-home-deep); box-shadow: inset 0 0 0 1px var(--dbt-home-line); overflow-x: auto; scrollbar-width: none; max-width: 100%; }
  .dbt-home-day {
    display: grid; justify-items: center; gap: 1px; min-width: 46px; padding: 5px 6px 4px; border-radius: 9px; color: var(--dbt-home-muted);
    transition: background-color 160ms, color 160ms;
    & small { font: 600 9.5px var(--dbt-home-mono); letter-spacing: 0.06em; text-transform: uppercase; }
    & b { font: 600 14px var(--dbt-home-mono); font-variant-numeric: tabular-nums; }
    & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
    &:hover { color: var(--dbt-home-ink); background: color-mix(in oklch, var(--dbt-home-ink) 5%, transparent); }
    &[aria-checked="true"] { background: var(--dbt-home-raise); color: var(--dbt-home-ink); box-shadow: inset 0 0 0 1px var(--dbt-home-line-2); }
    &[aria-checked="true"] svg { color: var(--dbt-home-sun); }
  }

  /* ---------- main ---------- */
  .dbt-home-main { grid-area: main; min-height: 0; min-width: 0; display: grid; padding: 0 22px 18px; }
  .dbt-home-view { min-height: 0; min-width: 0; display: grid; gap: 14px; transition: opacity 320ms var(--dbt-home-ease), translate 420ms var(--dbt-home-ease); @starting-style { opacity: 0; translate: 0 8px; } }
  .dbt-home-flowv { grid-template-columns: minmax(0, 1fr) 260px; grid-template-rows: minmax(0, 1fr) 196px; grid-template-areas: "flow totals" "chart chart"; }
  .dbt-home-weekv { grid-template-rows: minmax(0, 1fr) auto; }
  .dbt-home-circv { grid-template-columns: minmax(0, 1fr) 280px; }
  .dbt-home-panel { position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 14px; background: var(--dbt-home-panel); box-shadow: inset 0 0 0 1px var(--dbt-home-line); }
  .dbt-home-ph { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 14px; padding: 12px 14px 6px; & h3 { font-size: 13px; font-weight: 640; } }
  .dbt-home-hint { font: 11px var(--dbt-home-mono); color: var(--dbt-home-faint); }
  .dbt-home-keys {
    display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 11px; color: var(--dbt-home-muted);
    & li { display: inline-flex; align-items: center; gap: 6px; }
    & i { width: 12px; height: 8px; border-radius: 2px; }
    & [data-l="sun"] i, & [data-l="kept"] i { background: var(--dbt-home-sun); }
    & [data-l="exp"] i { background: repeating-linear-gradient(135deg, var(--dbt-home-sun) 0 2px, transparent 2px 4px); box-shadow: inset 0 0 0 1px var(--dbt-home-sun); }
    & [data-l="use"] i { height: 0; border-top: 2px solid var(--dbt-home-house); }
    & [data-l="soc"] i { height: 0; border-top: 2px dashed var(--dbt-home-batt); }
    & [data-l="peak"] i { background: color-mix(in oklch, var(--dbt-home-ev) 22%, transparent); }
    & [data-l="own"] i { background: var(--dbt-home-batt); }
    & [data-l="imp"] i { background: var(--dbt-home-grid); }
  }

  /* ---------- flow diagram ---------- */
  .dbt-home-flowp { grid-area: flow; overflow: hidden; background: radial-gradient(60% 70% at 50% 50%, color-mix(in oklch, var(--dbt-home-ink) 3%, transparent), transparent 70%), var(--dbt-home-panel); }
  .dbt-home-clock {
    position: absolute; left: 16px; top: 12px; z-index: 2; max-width: min(34%, 250px); display: grid; gap: 4px; pointer-events: none;
    & b { font: 600 clamp(22px, 2.6cqi, 30px)/1 var(--dbt-home-mono); letter-spacing: -0.04em; font-variant-numeric: tabular-nums; }
    & p { font-size: 12px; color: var(--dbt-home-muted); min-height: 3em; }
  }
  .dbt-home-diagram { position: relative; flex: 1; min-height: 0; margin: 8px 8px 0; }
  .dbt-home-lines { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dbt-home-track { fill: none; stroke: var(--dbt-home-line-2); stroke-width: 1.5; }
  .dbt-home-flow {
    fill: none; stroke: var(--c); stroke-linecap: round; stroke-dasharray: 0 13; stroke-width: var(--w, 4);
    opacity: var(--o, 0); transition: opacity 400ms, stroke-width 400ms var(--dbt-home-ease);
    filter: drop-shadow(0 0 4px color-mix(in oklch, var(--c) 60%, transparent));
  }
  .dbt-home-node {
    position: absolute; left: 0; top: 0; z-index: 1; display: grid; justify-items: center; gap: 2px; width: 104px; margin-left: -52px; margin-top: -32px;
    translate: var(--x, 0) var(--y, 0);
    animation: dbt-home-pop 640ms var(--dbt-home-spring) both; animation-delay: calc(var(--i) * 70ms + 120ms);
    --c: var(--dbt-home-ink);
    &[data-n="solar"] { --c: var(--dbt-home-sun); }
    &[data-n="grid"] { --c: var(--dbt-home-grid); }
    &[data-n="house"] { --c: var(--dbt-home-house); }
    &[data-n="batt"] { --c: var(--dbt-home-batt); }
    &[data-n="ev"] { --c: var(--dbt-home-ev); }
  }
  .dbt-home-node[data-n="solar"] {
    grid-template-columns: auto auto; grid-template-areas: "disc v" "disc l"; justify-items: start; align-items: center; column-gap: 10px; row-gap: 0; width: max-content; margin-left: -32px;
    & .dbt-home-disc { grid-area: disc; }
    & .dbt-home-nv { grid-area: v; align-self: end; margin: 0; }
    & .dbt-home-nl { grid-area: l; align-self: start; }
  }
  .dbt-home-disc {
    position: relative; display: grid; place-items: center; width: 64px; height: 64px; border-radius: 50%; overflow: hidden;
    background: var(--dbt-home-raise); box-shadow: 0 0 0 1px color-mix(in oklch, var(--c) 45%, transparent), 0 6px 18px -6px black;
    transition: box-shadow 400ms;
    & svg { position: relative; z-index: 1; width: 26px; height: 26px; fill: none; stroke: var(--c); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  }
  .dbt-home-node[data-active] .dbt-home-disc { animation: dbt-home-glow 2.4s ease-in-out infinite; }
  .dbt-home-batt .dbt-home-disc::before {
    content: ""; position: absolute; inset: 0; background: color-mix(in oklch, var(--dbt-home-batt) 30%, transparent);
    clip-path: inset(calc((100 - var(--dbt-home-soc)) * 1%) 0 0 0);
  }
  .dbt-home-batt { transition: --dbt-home-soc 600ms var(--dbt-home-ease); }
  .dbt-home-nv { display: flex; align-items: baseline; gap: 3px; margin-top: 4px; & b { font: 650 16px var(--dbt-home-mono); font-variant-numeric: tabular-nums; letter-spacing: -0.02em; } & small { font-size: 10.5px; color: var(--dbt-home-muted); } }
  .dbt-home-nl { font-size: 11px; color: var(--dbt-home-muted); white-space: nowrap; font-variant-numeric: tabular-nums; }
  .dbt-home-node[data-idle] .dbt-home-nv b { color: var(--dbt-home-faint); }
  .dbt-home-hub {
    position: absolute; left: 0; top: 0; z-index: 1; width: 40px; height: 40px; margin: -20px 0 0 -20px; display: grid; place-items: center; border-radius: 12px;
    translate: var(--x, 0) var(--y, 0); background: var(--dbt-home-deep); box-shadow: 0 0 0 1px var(--dbt-home-line-2);
    & svg { width: 20px; height: 20px; fill: none; stroke: var(--dbt-home-muted); stroke-width: 1.6; stroke-linecap: round; }
  }

  /* scrubber */
  .dbt-home-scrub { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 8px 14px 12px; }
  .dbt-home-play {
    width: 34px; height: 34px; display: grid; place-items: center; border-radius: 50%; background: var(--dbt-home-sun); color: var(--dbt-home-bg);
    transition: scale 200ms var(--dbt-home-spring), background-color 160ms;
    &:hover { scale: 1.06; } &:active { scale: 0.94; }
    & svg { width: 16px; height: 16px; fill: currentColor; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
    & .dbt-home-i-pause { display: none; fill: none; }
    &[aria-pressed="true"] .dbt-home-i-play { display: none; }
    &[aria-pressed="true"] .dbt-home-i-pause { display: block; }
  }
  .dbt-home-range { width: 100%; margin: 0; }
  .dbt-home-out { font: 600 12px var(--dbt-home-mono); color: var(--dbt-home-muted); font-variant-numeric: tabular-nums; min-width: 40px; text-align: right; }

  /* totals */
  .dbt-home-totals { grid-area: totals; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbt-home-line-2) transparent; padding: 12px 14px 12px; gap: 10px; }
  .dbt-home-ring {
    position: relative; width: 102px; height: 102px; margin: 0 auto; flex: none;
    & svg { width: 100%; height: 100%; rotate: -90deg; }
    & circle { fill: none; stroke-width: 9; }
    & .dbt-home-ring-bg { stroke: var(--dbt-home-line); }
    & .dbt-home-ring-fg { stroke: var(--dbt-home-batt); stroke-linecap: round; stroke-dasharray: var(--dbt-home-ring) 100; transition: --dbt-home-ring 1s var(--dbt-home-ease); }
    & div { position: absolute; inset: 0; display: grid; place-content: center; text-align: center; }
    & b { font: 650 26px/1 var(--dbt-home-mono); letter-spacing: -0.04em; font-variant-numeric: tabular-nums; }
    & small { font-size: 10px; color: var(--dbt-home-muted); max-width: 70px; line-height: 1.2; margin-top: 3px; }
  }
  .dbt-home-tlist {
    display: grid; gap: 1px;
    & div { display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 4px 2px; border-bottom: 1px solid var(--dbt-home-line); }
    & div::before { content: ""; width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
    & div[data-dash]::before { background: repeating-linear-gradient(135deg, var(--c) 0 2px, transparent 2px 4px); box-shadow: inset 0 0 0 1px var(--c); }
    & dt { font-size: 12px; color: var(--dbt-home-muted); }
    & dd { font: 600 12px var(--dbt-home-mono); font-variant-numeric: tabular-nums; }
  }
  .dbt-home-cost {
    display: grid; grid-template-columns: 1fr auto; align-items: baseline; gap: 0 8px; margin-top: auto;
    & span { font-size: 12px; color: var(--dbt-home-muted); }
    & b { font: 650 20px var(--dbt-home-mono); letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
    & small { grid-column: 1 / -1; font: 10.5px var(--dbt-home-mono); color: var(--dbt-home-faint); }
  }

  /* charts */
  .dbt-home-chartp { grid-area: chart; }
  .dbt-home-plot, .dbt-home-wplot, .dbt-home-cplot { position: relative; flex: 1; min-height: 0; margin: 0 6px 6px; touch-action: pan-y; }
  .dbt-home-plot { cursor: ew-resize; border-radius: 8px; }
  .dbt-home-svg, .dbt-home-wsvg, .dbt-home-csvg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dbt-home-ax line { stroke: var(--dbt-home-line); shape-rendering: crispEdges; }
  .dbt-home-ax text, .dbt-home-svg text, .dbt-home-wsvg text, .dbt-home-csvg text { font: 10px var(--dbt-home-mono); fill: var(--dbt-home-faint); font-variant-numeric: tabular-nums; }
  .dbt-home-peakband { fill: color-mix(in oklch, var(--dbt-home-ev) 8%, transparent); }
  .dbt-home-sunarea { fill: color-mix(in oklch, var(--dbt-home-sun) 30%, transparent); stroke: var(--dbt-home-sun); stroke-width: 1.5; transform-box: fill-box; transform-origin: 50% 100%; animation: dbt-home-grow 900ms var(--dbt-home-ease) both; }
  .dbt-home-useline { fill: none; stroke: var(--dbt-home-house); stroke-width: 2; stroke-linejoin: round; animation: dbt-home-draw 1.2s var(--dbt-home-ease) both 150ms; stroke-dasharray: 1; }
  .dbt-home-socline { fill: none; stroke: var(--dbt-home-batt); stroke-width: 1.6; stroke-dasharray: 4 3; opacity: 0.9; }
  .dbt-home-cur { pointer-events: none; & line { stroke: var(--dbt-home-ink); stroke-width: 1.5; } & circle { fill: var(--dbt-home-bg); stroke: var(--dbt-home-ink); stroke-width: 2; } }
  .dbt-home-ghost { pointer-events: none; opacity: 0; transition: opacity 120ms; & line { stroke: var(--dbt-home-ink); stroke-opacity: 0.5; stroke-dasharray: 2 3; } }
  .dbt-home-ghost[data-on] { opacity: 1; }

  .dbt-home-tip {
    position: absolute; left: 0; top: 0; z-index: 4; min-width: 170px; padding: 8px 10px; border-radius: 10px; pointer-events: none;
    background: color-mix(in oklch, var(--dbt-home-deep) 92%, transparent); box-shadow: 0 0 0 1px var(--dbt-home-line-2), 0 10px 30px -8px black;
    backdrop-filter: blur(6px); font-size: 11.5px; opacity: 0; scale: 0.96; transition: opacity 120ms, scale 160ms var(--dbt-home-ease);
    &[data-on] { opacity: 1; scale: 1; }
    & h4 { margin: 0 0 5px; font: 600 10.5px var(--dbt-home-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--dbt-home-muted); }
    & li { display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; gap: 7px; align-items: center; }
    & li i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
    & li b { font: 600 11.5px var(--dbt-home-mono); font-variant-numeric: tabular-nums; }
  }

  /* week */
  .dbt-home-wbar { transform-box: fill-box; transform-origin: 50% 100%; animation: dbt-home-grow 700ms var(--dbt-home-ease) both; animation-delay: calc(var(--i) * 55ms); }
  .dbt-home-whit { fill: transparent; cursor: pointer; }
  .dbt-home-whit:hover, .dbt-home-whit[data-sel] { fill: color-mix(in oklch, var(--dbt-home-ink) 5%, transparent); }
  .dbt-home-scroll { overflow: auto; max-height: 100%; scrollbar-width: thin; scrollbar-color: var(--dbt-home-line-2) transparent; }
  .dbt-home-table {
    width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums;
    & th, & td { padding: 7px 14px; text-align: right; white-space: nowrap; }
    & th:first-child, & td:first-child { text-align: left; }
    & thead th { position: sticky; top: 0; background: var(--dbt-home-panel); font: 600 10px var(--dbt-home-mono); letter-spacing: 0.07em; text-transform: uppercase; color: var(--dbt-home-muted); border-bottom: 1px solid var(--dbt-home-line); }
    & tbody tr { border-top: 1px solid var(--dbt-home-line); cursor: pointer; transition: background-color 140ms; }
    & tbody tr:hover { background: color-mix(in oklch, var(--dbt-home-ink) 4%, transparent); }
    & tbody tr[aria-selected="true"] { background: color-mix(in oklch, var(--dbt-home-sun) 10%, transparent); }
    & tbody tr[aria-selected="true"] td:first-child { color: var(--dbt-home-sun); }
    & td { font: 12px var(--dbt-home-mono); }
    & td:first-child { font: 560 12.5px system-ui, sans-serif; }
    & tfoot td { border-top: 1px solid var(--dbt-home-line-2); font-weight: 700; }
  }

  /* circuits */
  .dbt-home-cbar { transition: opacity 200ms; }
  .dbt-home-cchart:has(~ .dbt-home-clist .dbt-home-circ[aria-selected="true"]) .dbt-home-cbar:not([data-sel]) { opacity: 0.18; }
  .dbt-home-circs { flex: 1; min-height: 0; overflow: auto; padding: 4px 8px 10px; display: grid; align-content: start; gap: 2px; scrollbar-width: thin; scrollbar-color: var(--dbt-home-line-2) transparent; }
  .dbt-home-circ {
    display: grid; grid-template-columns: 10px minmax(0, 1fr) auto; gap: 4px 9px; align-items: center; padding: 8px 8px; border-radius: 9px; cursor: pointer;
    animation: dbt-home-rise 480ms var(--dbt-home-ease) both; animation-delay: calc(var(--i) * 45ms);
    transition: background-color 140ms;
    & > i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
    & span { font-weight: 560; font-size: 12.5px; }
    & b { font: 600 12px var(--dbt-home-mono); font-variant-numeric: tabular-nums; }
    & b small { margin-left: 6px; font-weight: 400; color: var(--dbt-home-faint); }
    & .dbt-home-cmeter { grid-column: 2 / -1; height: 4px; border-radius: 4px; background: var(--dbt-home-line); overflow: hidden; }
    & .dbt-home-cmeter i { display: block; height: 100%; width: calc(var(--s) * 100%); background: var(--c); border-radius: inherit; }
    &:hover { background: color-mix(in oklch, var(--dbt-home-ink) 4%, transparent); }
    &[aria-selected="true"] { background: var(--dbt-home-raise); box-shadow: inset 0 0 0 1px var(--dbt-home-line-2); }
    &[data-focus] { outline: 2px solid var(--dbt-home-sun); outline-offset: -2px; }
  }
  .dbt-home-ctot { font: 600 12px var(--dbt-home-mono); color: var(--dbt-home-muted); }

  /* ---------- responsive ---------- */
  @container (max-width: 1060px) {
    .dbt-home-flowv { grid-template-columns: minmax(0, 1fr) 228px; }
    .dbt-home-circv { grid-template-columns: minmax(0, 1fr) 240px; }
  }
  @container (max-width: 960px) {
    .dbt-home-app { grid-template-columns: 62px minmax(0, 1fr); }
    .dbt-home-side { align-items: center; padding-inline: 8px; }
    .dbt-home-brand { padding: 0; }
    .dbt-home-brand span, .dbt-home-navbtn span, .dbt-home-sys { display: none; }
    .dbt-home-navbtn { justify-content: center; padding: 10px; }
  }
  @container (max-width: 760px) {
    .dbt-home-app { display: flex; flex-direction: column; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbt-home-line-2) transparent; }
    .dbt-home-side { position: sticky; top: 0; z-index: 6; flex: none; flex-direction: row; justify-content: space-between; align-items: center; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dbt-home-line); }
    .dbt-home-nav { display: flex; gap: 4px; }
    .dbt-home-head { padding: 14px 14px 12px; }
    .dbt-home-main { display: block; padding: 0 14px 14px; }
    .dbt-home-view { display: flex; flex-direction: column; }
    .dbt-home-flowp { height: 400px; flex: none; }
    .dbt-home-chartp { height: 230px; flex: none; }
    .dbt-home-totals { overflow: visible; }
    .dbt-home-wchart, .dbt-home-cchart { height: 300px; flex: none; }
    .dbt-home-circs { overflow: visible; }
    .dbt-home-clock { position: static; max-width: none; padding: 12px 14px 0; }
    .dbt-home-clock p { min-height: 0; }
    .dbt-home-flowp { height: 470px; }
  }
  @container (max-width: 440px) {
    .dbt-home-flowp { height: 450px; }
    .dbt-home-disc { width: 50px; height: 50px; & svg { width: 21px; height: 21px; } }
    .dbt-home-node { width: 84px; margin-left: -42px; margin-top: -25px; }
