    <li style="--c:var(--dbt-home-batt)"><i></i><span>Battery ${s.B < -0.05 ? 'in' : s.B > 0.05 ? 'out' : ''}</span><b>${f1(Math.abs(s.B))} kW · ${Math.round(s.soc)}%</b></li>
