css:
@keyframes dbt-fleet-ping { from { r: 9; opacity: 0.7; } to { r: 22; opacity: 0; } }
@keyframes dbt-fleet-blink { 50% { opacity: 0.25; } }
@keyframes dbt-fleet-row { from { opacity: 0; translate: 0 14px; } }
@keyframes dbt-fleet-in { from { opacity: 0; translate: 0 8px; scale: 0.98; } }

.dbt-fleet {
  /* re-theme: paper, ink, accent; status hues below */
  --dbt-fleet-bg: oklch(0.975 0.01 95);
  --dbt-fleet-ink: oklch(0.26 0.025 255);
  --dbt-fleet-accent: oklch(0.47 0.11 165);
  --dbt-fleet-route: oklch(0.52 0.14 252);
  --dbt-fleet-delayed: oklch(0.6 0.2 30);
  --dbt-fleet-charging: oklch(0.74 0.15 78);
  --dbt-fleet-idle: oklch(0.62 0.015 255);
  /* map */
  --dbt-fleet-land: color-mix(in oklch, var(--dbt-fleet-bg), oklch(0.93 0.02 90) 60%);
  --dbt-fleet-block: color-mix(in oklch, var(--dbt-fleet-land), var(--dbt-fleet-ink) 6%);
  --dbt-fleet-park: oklch(0.89 0.06 142);
  --dbt-fleet-water: oklch(0.85 0.05 228);
  --dbt-fleet-road: oklch(0.995 0 0);
  --dbt-fleet-casing: color-mix(in oklch, var(--dbt-fleet-land), var(--dbt-fleet-ink) 14%);
  --dbt-fleet-major: oklch(0.95 0.06 92);
  /* derived */
  --dbt-fleet-panel: color-mix(in oklch, var(--dbt-fleet-bg), white 60%);
  --dbt-fleet-side-bg: color-mix(in oklch, var(--dbt-fleet-bg), var(--dbt-fleet-ink) 4%);
  --dbt-fleet-line: color-mix(in oklch, var(--dbt-fleet-ink) 11%, transparent);
  --dbt-fleet-line-2: color-mix(in oklch, var(--dbt-fleet-ink) 20%, transparent);
  --dbt-fleet-muted: color-mix(in oklch, var(--dbt-fleet-ink) 62%, var(--dbt-fleet-bg));
  --dbt-fleet-faint: color-mix(in oklch, var(--dbt-fleet-ink) 40%, var(--dbt-fleet-bg));
  --dbt-fleet-hover: color-mix(in oklch, var(--dbt-fleet-ink) 5%, transparent);
  --dbt-fleet-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dbt-fleet-spring: linear(0, 0.013, 0.05 2.4%, 0.2 5.3%, 0.81 14%, 0.99 18%, 1.07 21.6%, 1.08 25%, 1.05 30%, 1.007 37.5%, 0.994 45%, 1);
  --dbt-fleet-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbt-fleet-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbt-fleet-bg);
  color: var(--dbt-fleet-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light;
  accent-color: var(--dbt-fleet-accent);
  box-shadow: inset 0 0 0 1px var(--dbt-fleet-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbt-fleet-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ol, & ul { list-style: none; margin: 0; padding: 0; }
  & dl, & dd { margin: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbt-fleet-eyebrow { display: flex; align-items: center; gap: 7px; font: 600 10px/1.3 var(--dbt-fleet-mono); letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbt-fleet-muted); }
  .dbt-fleet-live { width: 7px; height: 7px; border-radius: 50%; background: var(--dbt-fleet-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--dbt-fleet-accent) 22%, transparent); animation: dbt-fleet-blink 1.6s ease-in-out infinite; }

  .dbt-fleet-app { display: grid; height: 100%; grid-template-columns: 196px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side head" "side main"; }

  /* ---------- side ---------- */
  .dbt-fleet-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; background: var(--dbt-fleet-side-bg); border-right: 1px solid var(--dbt-fleet-line); }
  .dbt-fleet-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbt-fleet-brand svg { width: 32px; height: 32px; flex: none; padding: 5px; border-radius: 9px; background: var(--dbt-fleet-accent); fill: none; stroke: var(--dbt-fleet-bg); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbt-fleet-brand span { display: grid; line-height: 1.2; min-width: 0; }
  .dbt-fleet-brand b { font-weight: 700; letter-spacing: -0.01em; }
  .dbt-fleet-brand small { font-size: 11px; color: var(--dbt-fleet-muted); white-space: nowrap; }
  .dbt-fleet-nav { display: grid; gap: 2px; }
  .dbt-fleet-navbtn {
    position: relative; display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px 10px; border-radius: 8px; color: var(--dbt-fleet-muted); font-weight: 560;
    transition: color 160ms, background-color 160ms;
    & svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
    &:hover { color: var(--dbt-fleet-ink); background: var(--dbt-fleet-hover); }
    &[aria-selected="true"] { color: var(--dbt-fleet-ink); background: var(--dbt-fleet-panel); box-shadow: 0 0 0 1px var(--dbt-fleet-line), 0 1px 2px color-mix(in oklch, var(--dbt-fleet-ink) 8%, transparent); }
    &[aria-selected="true"] svg { color: var(--dbt-fleet-accent); }
  }
  .dbt-fleet-badge { margin-left: auto; min-width: 20px; padding: 0 6px; border-radius: 99px; font: 650 10.5px/18px var(--dbt-fleet-mono); font-style: normal; text-align: center; background: var(--dbt-fleet-delayed); color: white; transition: scale 300ms var(--dbt-fleet-spring); }
  .dbt-fleet-badge[data-zero] { background: var(--dbt-fleet-line); color: var(--dbt-fleet-muted); }
  .dbt-fleet-foot { margin-top: auto; display: grid; gap: 8px; padding: 14px 8px 0; border-top: 1px solid var(--dbt-fleet-line); }
  .dbt-fleet-bays { display: grid; grid-template-columns: repeat(6, 1fr); gap: 4px; }
  .dbt-fleet-bay { height: 26px; border-radius: 5px; box-shadow: inset 0 0 0 1px var(--dbt-fleet-line-2); position: relative; overflow: hidden; transition: background-color 300ms; }
  .dbt-fleet-bay[data-on] { background: color-mix(in oklch, var(--dbt-fleet-charging) 22%, transparent); box-shadow: inset 0 0 0 1px var(--dbt-fleet-charging); }
  .dbt-fleet-bay[data-on]::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: var(--soc); background: var(--dbt-fleet-charging); transition: height 600ms var(--dbt-fleet-ease); }
  .dbt-fleet-footnote { font-size: 11.5px; color: var(--dbt-fleet-muted); & b { color: var(--dbt-fleet-ink); font-family: var(--dbt-fleet-mono); } }

  /* ---------- head ---------- */
  .dbt-fleet-head { grid-area: head; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px 24px; padding: 16px 20px 14px; min-width: 0; }
  .dbt-fleet-titles { display: grid; gap: 4px; }
  .dbt-fleet-h { font-size: clamp(20px, 2.3cqi, 27px); font-weight: 680; letter-spacing: -0.025em; line-height: 1.05; }
  .dbt-fleet-kpis {
    display: flex; gap: 0;
    & div { padding: 0 18px; border-left: 1px solid var(--dbt-fleet-line); }
    & div:first-child { border-left: 0; padding-left: 0; }
    & div:last-child { padding-right: 0; }
    & dt { font-size: 11px; color: var(--dbt-fleet-muted); font-weight: 560; white-space: nowrap; }
    & dd { display: flex; align-items: baseline; gap: 4px; white-space: nowrap; }
    & b { font-size: clamp(19px, 2.1cqi, 25px); font-weight: 650; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
    & small { font-size: 11.5px; color: var(--dbt-fleet-muted); font-variant-numeric: tabular-nums; }
  }

  /* ---------- main ---------- */
  .dbt-fleet-main { grid-area: main; min-height: 0; min-width: 0; display: grid; padding: 0 20px 18px; }
  .dbt-fleet-view { min-height: 0; min-width: 0; display: grid; gap: 14px; transition: opacity 320ms var(--dbt-fleet-ease), translate 420ms var(--dbt-fleet-ease); @starting-style { opacity: 0; translate: 0 8px; } }
  .dbt-fleet-mapv { grid-template-columns: minmax(0, 1fr) 300px; }
  .dbt-fleet-rangev { grid-template-columns: minmax(0, 1fr) minmax(0, 0.95fr); }
  .dbt-fleet-panel { position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dbt-fleet-panel); box-shadow: 0 0 0 1px var(--dbt-fleet-line), 0 1px 3px color-mix(in oklch, var(--dbt-fleet-ink) 5%, transparent); }
  .dbt-fleet-ph { display: grid; gap: 2px; padding: 12px 14px 6px; & h3 { font-size: 13px; font-weight: 650; } }
  .dbt-fleet-hint { font-size: 11.5px; color: var(--dbt-fleet-faint); }

  /* ---------- map ---------- */
  .dbt-fleet-mapwrap { position: relative; min-height: 0; border-radius: 12px; overflow: hidden; background: var(--dbt-fleet-land); box-shadow: 0 0 0 1px var(--dbt-fleet-line-2); }
  .dbt-fleet-map { position: absolute; inset: 0; width: 100%; height: 100%; cursor: grab; touch-action: none; border-radius: inherit; }
  .dbt-fleet-map:active { cursor: grabbing; }
  .dbt-fleet-map:focus-visible { outline-offset: -3px; }
  .dbt-fleet-map text { font-family: system-ui, sans-serif; pointer-events: none; }
  .dbt-fleet-blk { fill: var(--dbt-fleet-block); }
  .dbt-fleet-parkp { fill: var(--dbt-fleet-park); }
  .dbt-fleet-tree { fill: color-mix(in oklch, var(--dbt-fleet-park), var(--dbt-fleet-ink) 12%); }
  .dbt-fleet-wat { fill: var(--dbt-fleet-water); }
  .dbt-fleet-riv { fill: none; stroke: var(--dbt-fleet-water); stroke-width: 26; stroke-linecap: round; }
  .dbt-fleet-rc { fill: none; stroke: var(--dbt-fleet-casing); stroke-linecap: round; }
  .dbt-fleet-rf { fill: none; stroke: var(--dbt-fleet-road); stroke-linecap: round; }
  .dbt-fleet-rf.dbt-fleet-maj { stroke: var(--dbt-fleet-major); }
  .dbt-fleet-bridge { fill: none; stroke: var(--dbt-fleet-casing); stroke-width: 1.4; }
  .dbt-fleet-dist { font-size: 11px; font-weight: 700; letter-spacing: 0.22em; fill: color-mix(in oklch, var(--dbt-fleet-ink) 34%, var(--dbt-fleet-land)); text-transform: uppercase; }
  .dbt-fleet-wlbl { font-size: 12px; font-style: italic; fill: color-mix(in oklch, var(--dbt-fleet-water), var(--dbt-fleet-ink) 45%); letter-spacing: 0.06em; }
  .dbt-fleet-slbl { font-size: 8.5px; fill: var(--dbt-fleet-faint); letter-spacing: 0.04em; }
  .dbt-fleet-depot rect { fill: var(--dbt-fleet-panel); stroke: var(--dbt-fleet-ink); stroke-width: 1.2; }
  .dbt-fleet-depot text { font-size: 9px; font-weight: 700; fill: var(--dbt-fleet-ink); letter-spacing: 0.08em; }
  .dbt-fleet-rhid { visibility: hidden; }
  .dbt-fleet-selc { fill: none; stroke: white; stroke-linecap: round; stroke-linejoin: round; }
  .dbt-fleet-seldone { fill: none; stroke: var(--dbt-fleet-faint); stroke-linecap: round; stroke-linejoin: round; stroke-opacity: 0.7; }
  .dbt-fleet-seltodo { fill: none; stroke: var(--dbt-fleet-ink); stroke-linecap: round; stroke-linejoin: round; }
  .dbt-fleet-stop { & circle { fill: var(--dbt-fleet-panel); stroke: var(--dbt-fleet-ink); } & text { font: 700 7px var(--dbt-fleet-mono); fill: var(--dbt-fleet-ink); text-anchor: middle; dominant-baseline: central; } }
  .dbt-fleet-stop[data-done] { & circle { fill: var(--dbt-fleet-faint); stroke: var(--dbt-fleet-panel); } & text { fill: var(--dbt-fleet-panel); } }
  .dbt-fleet-stop[data-next] circle { fill: var(--dbt-fleet-ink); } .dbt-fleet-stop[data-next] text { fill: var(--dbt-fleet-panel); }
  .dbt-fleet-van { cursor: pointer; transition: opacity 250ms; }
  .dbt-fleet-van .dbt-fleet-vb { stroke: white; stroke-width: 2; fill: var(--sc); transition: fill 300ms; }
  .dbt-fleet-van .dbt-fleet-vh { fill: white; }
  .dbt-fleet-van .dbt-fleet-ring { fill: none; stroke: var(--sc); stroke-width: 2; opacity: 0; }
  .dbt-fleet-van[data-s="delayed"] .dbt-fleet-ring { animation: dbt-fleet-ping 1.8s cubic-bezier(0.2, 0.7, 0.3, 1) infinite; }
  .dbt-fleet-van .dbt-fleet-vl { font: 700 9px var(--dbt-fleet-mono); fill: var(--dbt-fleet-ink); paint-order: stroke; stroke: var(--dbt-fleet-panel); stroke-width: 3px; stroke-linejoin: round; opacity: 0; transition: opacity 200ms; }
  .dbt-fleet-van:hover .dbt-fleet-vl, .dbt-fleet-van[data-sel] .dbt-fleet-vl, .dbt-fleet-map[data-zoomed] .dbt-fleet-vl { opacity: 1; }
  .dbt-fleet-van[data-sel] .dbt-fleet-vb { stroke: var(--dbt-fleet-ink); stroke-width: 2.5; }
  .dbt-fleet-van[data-dim] { opacity: 0.22; }
  .dbt-fleet-van[data-s="route"] { --sc: var(--dbt-fleet-route); }
  .dbt-fleet-van[data-s="delayed"] { --sc: var(--dbt-fleet-delayed); }
  .dbt-fleet-van[data-s="charging"] { --sc: var(--dbt-fleet-charging); }
  .dbt-fleet-van[data-s="idle"] { --sc: var(--dbt-fleet-idle); }

  .dbt-fleet-zoom {
    position: absolute; right: 12px; top: 12px; display: grid; border-radius: 10px; overflow: hidden; background: var(--dbt-fleet-panel); box-shadow: 0 0 0 1px var(--dbt-fleet-line-2), 0 4px 12px color-mix(in oklch, var(--dbt-fleet-ink) 12%, transparent);
    & button { width: 32px; height: 32px; display: grid; place-items: center; transition: background-color 140ms; }
    & button + button { border-top: 1px solid var(--dbt-fleet-line); }
    & button:hover { background: var(--dbt-fleet-hover); }
    & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  }
  .dbt-fleet-legend {
    position: absolute; left: 12px; top: 12px; display: flex; flex-wrap: wrap; gap: 4px 12px; padding: 6px 10px; border-radius: 9px; font-size: 11px; font-weight: 560;
    background: color-mix(in oklch, var(--dbt-fleet-panel) 88%, transparent); box-shadow: 0 0 0 1px var(--dbt-fleet-line); backdrop-filter: blur(6px);
    & li { display: inline-flex; align-items: center; gap: 6px; }
    & i { width: 9px; height: 9px; border-radius: 50%; box-shadow: 0 0 0 1.5px white, 0 0 0 2.5px var(--dbt-fleet-line-2); }
    & [data-s="route"] i { background: var(--dbt-fleet-route); }
    & [data-s="delayed"] i { background: var(--dbt-fleet-delayed); }
    & [data-s="charging"] i { background: var(--dbt-fleet-charging); }
    & [data-s="idle"] i { background: var(--dbt-fleet-idle); }
  }

  /* detail card, inside the map */
  .dbt-fleet-card {
    position: absolute; left: 12px; bottom: 12px; width: min(300px, calc(100% - 24px)); padding: 12px 14px 12px; border-radius: 12px; z-index: 3;
    background: var(--dbt-fleet-panel); box-shadow: 0 0 0 1px var(--dbt-fleet-line-2), 0 14px 34px -8px color-mix(in oklch, var(--dbt-fleet-ink) 30%, transparent);
    transition: opacity 260ms var(--dbt-fleet-ease), translate 360ms var(--dbt-fleet-spring);
    @starting-style { opacity: 0; translate: 0 14px; }
  }
  .dbt-fleet-ch { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0 10px; align-items: start; }
  .dbt-fleet-ch b { font: 700 15px var(--dbt-fleet-mono); letter-spacing: -0.02em; }
  .dbt-fleet-ch small { grid-column: 1; font-size: 12px; color: var(--dbt-fleet-muted); }
  .dbt-fleet-x { grid-row: 1 / 3; grid-column: 2; width: 26px; height: 26px; display: grid; place-items: center; border-radius: 7px; color: var(--dbt-fleet-muted); &:hover { background: var(--dbt-fleet-hover); color: var(--dbt-fleet-ink); } & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; } }
  .dbt-fleet-pill { display: inline-flex; align-items: center; gap: 6px; margin-top: 8px; padding: 2px 9px 2px 7px; border-radius: 99px; font-size: 11.5px; font-weight: 600; background: color-mix(in oklch, var(--sc) 14%, transparent); color: color-mix(in oklch, var(--sc), var(--dbt-fleet-ink) 35%); & i { width: 7px; height: 7px; border-radius: 50%; background: var(--sc); } }
  .dbt-fleet-cgrid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--dbt-fleet-line); & dt { font-size: 10.5px; color: var(--dbt-fleet-muted); } & dd { font: 600 13px var(--dbt-fleet-mono); font-variant-numeric: tabular-nums; } }
  .dbt-fleet-dots { display: flex; gap: 3px; margin-top: 10px; & i { flex: 1; height: 5px; border-radius: 3px; background: var(--dbt-fleet-line-2); } & i[data-d] { background: var(--dbt-fleet-ink); } & i[data-n] { background: var(--dbt-fleet-accent); } }
  .dbt-fleet-next { margin-top: 8px; font-size: 12px; color: var(--dbt-fleet-muted); & b { color: var(--dbt-fleet-ink); font-weight: 600; } }
  .dbt-fleet-follow { display: flex; align-items: center; gap: 8px; margin-top: 10px; font-size: 12px; font-weight: 560; cursor: pointer; }
  .dbt-fleet-follow input { margin: 0; width: 15px; height: 15px; }

  /* ---------- list ---------- */
  .dbt-fleet-listp { overflow: hidden; }
  .dbt-fleet-tools { display: grid; gap: 8px; padding: 12px 12px 8px; border-bottom: 1px solid var(--dbt-fleet-line); }
  .dbt-fleet-search {
    display: flex; align-items: center; gap: 8px; padding: 0 10px; height: 32px; border-radius: 9px; background: var(--dbt-fleet-bg); box-shadow: inset 0 0 0 1px var(--dbt-fleet-line-2); transition: box-shadow 160ms;
    &:focus-within { box-shadow: inset 0 0 0 1.5px var(--dbt-fleet-accent), 0 0 0 3px color-mix(in oklch, var(--dbt-fleet-accent) 15%, transparent); }
    & svg { width: 15px; height: 15px; flex: none; fill: none; stroke: var(--dbt-fleet-muted); stroke-width: 1.8; stroke-linecap: round; }
    & input { flex: 1; min-width: 0; border: 0; background: none; font: inherit; color: inherit; outline: none; }
    & input::placeholder { color: var(--dbt-fleet-faint); }
  }
  .dbt-fleet-chips {
    display: flex; flex-wrap: wrap; gap: 4px;
    & button { display: inline-flex; align-items: center; gap: 5px; padding: 3px 8px; border-radius: 99px; font-size: 11.5px; font-weight: 560; color: var(--dbt-fleet-muted); box-shadow: inset 0 0 0 1px var(--dbt-fleet-line-2); transition: background-color 160ms, color 160ms, box-shadow 160ms; }
    & button b { font: 650 10.5px var(--dbt-fleet-mono); color: var(--dbt-fleet-faint); }
    & button:hover { color: var(--dbt-fleet-ink); }
    & button[aria-pressed="true"] { background: var(--dbt-fleet-ink); color: var(--dbt-fleet-panel); box-shadow: none; }
    & button[aria-pressed="true"] b { color: color-mix(in oklch, var(--dbt-fleet-panel) 70%, transparent); }
  }
  .dbt-fleet-list { flex: 1; min-height: 0; overflow: auto; padding: 6px; scrollbar-width: thin; scrollbar-color: var(--dbt-fleet-line-2) transparent; outline: none; }
  .dbt-fleet-list:focus-visible { box-shadow: inset 0 0 0 2px var(--dbt-fleet-accent); border-radius: 0 0 12px 12px; }
  .dbt-fleet-item {
    display: grid; grid-template-columns: 10px minmax(0, 1fr) auto; grid-template-areas: "dot who soc" "dot what eta"; gap: 1px 10px; align-items: center; padding: 8px 10px; border-radius: 9px; cursor: pointer;
    transition: background-color 140ms;
    --sc: var(--dbt-fleet-idle);
    &[data-s="route"] { --sc: var(--dbt-fleet-route); }
    &[data-s="delayed"] { --sc: var(--dbt-fleet-delayed); }
    &[data-s="charging"] { --sc: var(--dbt-fleet-charging); }
    & > i { grid-area: dot; width: 9px; height: 9px; border-radius: 50%; background: var(--sc); align-self: start; margin-top: 5px; }
    & .dbt-fleet-who { grid-area: who; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 12.5px; }
    & .dbt-fleet-who b { font: 700 12px var(--dbt-fleet-mono); margin-right: 6px; }
    & .dbt-fleet-what { grid-area: what; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 11.5px; color: var(--dbt-fleet-muted); }
    & .dbt-fleet-soc { grid-area: soc; display: flex; align-items: center; gap: 6px; font: 600 11px var(--dbt-fleet-mono); font-variant-numeric: tabular-nums; }
    & .dbt-fleet-soc i { width: 26px; height: 8px; border-radius: 2px; box-shadow: inset 0 0 0 1px var(--dbt-fleet-line-2); background: linear-gradient(90deg, var(--bc) var(--w), transparent var(--w)); }
    & .dbt-fleet-eta { grid-area: eta; justify-self: end; font: 11px var(--dbt-fleet-mono); color: var(--dbt-fleet-faint); font-variant-numeric: tabular-nums; }
    &:hover { background: var(--dbt-fleet-hover); }
    &[aria-selected="true"] { background: color-mix(in oklch, var(--dbt-fleet-accent) 10%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbt-fleet-accent) 35%, transparent); }
    &[data-focus] { outline: 2px solid var(--dbt-fleet-accent); outline-offset: -2px; }
  }
  @supports (animation-timeline: view()) {
    .dbt-fleet-item { animation: dbt-fleet-row linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
  }
  .dbt-fleet-empty { padding: 20px; text-align: center; color: var(--dbt-fleet-faint); font-size: 12px; }

  /* ---------- range view ---------- */
  .dbt-fleet-splot { position: relative; flex: 1; min-height: 0; margin: 0 8px 8px; }
  .dbt-fleet-ssvg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dbt-fleet-ssvg text { font: 10px var(--dbt-fleet-mono); fill: var(--dbt-fleet-faint); }
  .dbt-fleet-ssvg .dbt-fleet-ax line { stroke: var(--dbt-fleet-line); shape-rendering: crispEdges; }
  .dbt-fleet-riskz { fill: color-mix(in oklch, var(--dbt-fleet-delayed) 8%, transparent); }
  .dbt-fleet-diag { stroke: var(--dbt-fleet-delayed); stroke-width: 1.4; stroke-dasharray: 5 4; }
  .dbt-fleet-diaglbl { fill: var(--dbt-fleet-delayed) !important; font-weight: 600; }
  .dbt-fleet-pt { cursor: pointer; transition: translate 600ms var(--dbt-fleet-spring); }
  .dbt-fleet-pt circle { fill: var(--sc); stroke: white; stroke-width: 2; transition: r 200ms var(--dbt-fleet-ease); }
  .dbt-fleet-pt text { font: 700 9.5px var(--dbt-fleet-mono) !important; fill: var(--dbt-fleet-ink) !important; paint-order: stroke; stroke: var(--dbt-fleet-panel); stroke-width: 3px; }
  .dbt-fleet-pt:hover circle, .dbt-fleet-pt[data-sel] circle { r: 9; }
  .dbt-fleet-pt[data-sel] circle { stroke: var(--dbt-fleet-ink); }
  .dbt-fleet-proj { fill: none; stroke: var(--dbt-fleet-accent); stroke-width: 1.6; stroke-dasharray: 3 3; }
  .dbt-fleet-projc { fill: var(--dbt-fleet-panel); stroke: var(--dbt-fleet-accent); stroke-width: 2; stroke-dasharray: 2 2; }
  .dbt-fleet-tip {
    position: absolute; left: 0; top: 0; z-index: 3; padding: 8px 10px; border-radius: 9px; pointer-events: none; min-width: 160px; font-size: 11.5px;
    background: var(--dbt-fleet-ink); color: var(--dbt-fleet-bg); box-shadow: 0 10px 24px color-mix(in oklch, var(--dbt-fleet-ink) 25%, transparent);
    opacity: 0; scale: 0.96; transition: opacity 120ms, scale 160ms var(--dbt-fleet-ease);
    &[data-on] { opacity: 1; scale: 1; }
    & b { font-family: var(--dbt-fleet-mono); }
    & p { display: flex; justify-content: space-between; gap: 14px; }
  }
  .dbt-fleet-scroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbt-fleet-line-2) transparent; }
  .dbt-fleet-table {
    width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums;
    & th, & td { padding: 8px 8px; text-align: right; white-space: nowrap; }
