@property --dbt-oee-v { syntax: "<number>"; inherits: true; initial-value: 0; }
@keyframes dbt-oee-in { from { opacity: 0; translate: 0 12px; } }
@keyframes dbt-oee-grow { from { scale: 1 0; } }
@keyframes dbt-oee-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dbt-oee-blink { 50% { opacity: 0.3; } }
@keyframes dbt-oee-cell { from { opacity: 0; scale: 0.6; } }

.dbt-oee {
  /* re-theme: background, ink, accent; state hues below */
  --dbt-oee-bg: oklch(0.2 0.008 255);
  --dbt-oee-ink: oklch(0.94 0.008 90);
  --dbt-oee-accent: oklch(0.86 0.17 95);
  --dbt-oee-run: oklch(0.72 0.14 155);
  --dbt-oee-fault: oklch(0.64 0.2 27);
  --dbt-oee-change: oklch(0.72 0.11 245);
  --dbt-oee-minor: oklch(0.8 0.13 72);
  --dbt-oee-break: oklch(0.5 0.01 255);
  --dbt-oee-panel: color-mix(in oklch, var(--dbt-oee-bg), white 4%);
  --dbt-oee-raise: color-mix(in oklch, var(--dbt-oee-bg), white 8%);
  --dbt-oee-deep: color-mix(in oklch, var(--dbt-oee-bg), black 30%);
  --dbt-oee-line: color-mix(in oklch, var(--dbt-oee-ink) 9%, transparent);
  --dbt-oee-line-2: color-mix(in oklch, var(--dbt-oee-ink) 17%, transparent);
  --dbt-oee-muted: color-mix(in oklch, var(--dbt-oee-ink) 60%, var(--dbt-oee-bg));
  --dbt-oee-faint: color-mix(in oklch, var(--dbt-oee-ink) 38%, var(--dbt-oee-bg));
  --dbt-oee-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dbt-oee-spring: linear(0, 0.013, 0.05 2.4%, 0.2 5.3%, 0.81 14%, 0.99 18%, 1.07 21.6%, 1.08 25%, 1.05 30%, 1.007 37.5%, 0.994 45%, 1);
  --dbt-oee-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbt-oee-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 12px;
  background: var(--dbt-oee-bg);
  color: var(--dbt-oee-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark;
  accent-color: var(--dbt-oee-accent);
  box-shadow: inset 0 0 0 1px var(--dbt-oee-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbt-oee-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ol, & ul { list-style: none; margin: 0; padding: 0; }
  & dl, & dd { margin: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbt-oee-eyebrow { display: flex; align-items: center; gap: 7px; font: 600 10px/1.3 var(--dbt-oee-mono); letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbt-oee-muted); & span { color: var(--dbt-oee-faint); letter-spacing: 0.04em; text-transform: none; } }
  .dbt-oee-live { width: 7px; height: 7px; border-radius: 1px; background: var(--dbt-oee-accent); animation: dbt-oee-blink 1.4s steps(2, jump-none) infinite; }

  .dbt-oee-app { display: grid; height: 100%; grid-template-columns: 188px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side head" "side main"; }

  /* ---------- side ---------- */
  .dbt-oee-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px 16px; background: var(--dbt-oee-deep); border-right: 1px solid var(--dbt-oee-line); }
  .dbt-oee-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbt-oee-brand svg { width: 32px; height: 32px; flex: none; padding: 5px; border-radius: 6px; background: var(--dbt-oee-accent); fill: none; stroke: var(--dbt-oee-bg); stroke-width: 1.7; stroke-linejoin: round; stroke-linecap: round; }
  .dbt-oee-brand span { display: grid; line-height: 1.2; min-width: 0; }
  .dbt-oee-brand b { font-weight: 750; letter-spacing: 0.02em; text-transform: uppercase; font-size: 13px; }
  .dbt-oee-brand small { font: 10.5px var(--dbt-oee-mono); color: var(--dbt-oee-muted); white-space: nowrap; }
  .dbt-oee-nav { display: grid; gap: 2px; }
  .dbt-oee-navbtn {
    position: relative; display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px 10px; border-radius: 7px; color: var(--dbt-oee-muted); font-weight: 560;
    transition: color 160ms, background-color 160ms;
    & svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
    &:hover { color: var(--dbt-oee-ink); background: color-mix(in oklch, var(--dbt-oee-ink) 5%, transparent); }
    &[aria-selected="true"] { color: var(--dbt-oee-ink); background: var(--dbt-oee-raise); }
    &[aria-selected="true"]::before { content: ""; position: absolute; left: -12px; top: 8px; bottom: 8px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dbt-oee-accent); }
    &[aria-selected="true"] svg { color: var(--dbt-oee-accent); }
  }
  .dbt-oee-legend {
    margin-top: auto; display: grid; gap: 8px; padding: 14px 8px 0; border-top: 1px solid var(--dbt-oee-line);
    & ul { display: grid; gap: 5px; }
    & li { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--dbt-oee-muted); }
    & i { width: 14px; height: 8px; border-radius: 2px; }
  }
  [data-c="run"] > i { background: var(--dbt-oee-run); }
  [data-c="minor"] > i { background: var(--dbt-oee-minor); }
  [data-c="change"] > i { background: var(--dbt-oee-change); }
  [data-c="fault"] > i { background: var(--dbt-oee-fault); }
  [data-c="break"] > i { background: repeating-linear-gradient(135deg, var(--dbt-oee-break) 0 2px, transparent 2px 4px); box-shadow: inset 0 0 0 1px var(--dbt-oee-break); }

  /* ---------- head ---------- */
  .dbt-oee-head { grid-area: head; display: grid; gap: 12px; padding: 16px 20px 12px; min-width: 0; }
  .dbt-oee-titlebar { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 20px; }
  .dbt-oee-titles { display: grid; gap: 4px; }
  .dbt-oee-h { font-size: clamp(20px, 2.3cqi, 27px); font-weight: 700; letter-spacing: -0.02em; line-height: 1.05; }
  .dbt-oee-shifts {
    display: inline-flex; gap: 2px; padding: 3px; border-radius: 9px; background: var(--dbt-oee-deep); box-shadow: inset 0 0 0 1px var(--dbt-oee-line);
    & button { display: grid; justify-items: start; padding: 4px 11px; border-radius: 6px; color: var(--dbt-oee-muted); transition: background-color 160ms, color 160ms; }
    & b { font-size: 12px; font-weight: 650; }
    & small { font: 10px var(--dbt-oee-mono); color: var(--dbt-oee-faint); }
    & button:hover { color: var(--dbt-oee-ink); }
    & button[aria-checked="true"] { background: var(--dbt-oee-raise); color: var(--dbt-oee-ink); box-shadow: inset 0 -2px 0 var(--dbt-oee-accent); }
  }
  .dbt-oee-kpis { display: grid; grid-template-columns: 1.15fr repeat(4, minmax(0, 1fr)); gap: 8px; }
  .dbt-oee-kpi {
    position: relative; padding: 9px 12px 10px; border-radius: 9px; background: var(--dbt-oee-panel); box-shadow: inset 0 0 0 1px var(--dbt-oee-line); min-width: 0;
    animation: dbt-oee-in 520ms var(--dbt-oee-ease) both; animation-delay: calc(var(--i, 0) * 50ms);
    & dt { font: 600 10px var(--dbt-oee-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbt-oee-muted); }
    & dd { display: flex; align-items: baseline; gap: 3px; margin-top: 2px; }
    & b { font-size: clamp(19px, 2.2cqi, 25px); font-weight: 650; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; line-height: 1.1; }
    & small { font-size: 12px; color: var(--dbt-oee-muted); }
  }
  .dbt-oee-kpi:nth-child(2) { --i: 1; } .dbt-oee-kpi:nth-child(3) { --i: 2; } .dbt-oee-kpi:nth-child(4) { --i: 3; } .dbt-oee-kpi:nth-child(5) { --i: 4; }
  .dbt-oee-kpi-main { background: color-mix(in srgb, var(--dbt-oee-accent) 9%, var(--dbt-oee-panel)); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dbt-oee-accent) 45%, transparent); & b { color: var(--dbt-oee-accent); } }
  .dbt-oee-kbar { display: block; height: 3px; margin-top: 6px; border-radius: 3px; background: var(--dbt-oee-line); overflow: hidden; & i { display: block; height: 100%; width: calc(var(--dbt-oee-v) * 1%); background: var(--dbt-oee-ink); border-radius: inherit; transition: --dbt-oee-v 900ms var(--dbt-oee-ease); } }
  .dbt-oee-kfoot { display: block; margin-top: 4px; font: 10.5px var(--dbt-oee-mono); color: var(--dbt-oee-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

  /* ---------- main ---------- */
  .dbt-oee-main { grid-area: main; min-height: 0; min-width: 0; display: grid; padding: 2px 20px 18px; }
  .dbt-oee-view { min-height: 0; min-width: 0; display: grid; gap: 14px; transition: opacity 320ms var(--dbt-oee-ease), translate 420ms var(--dbt-oee-ease); @starting-style { opacity: 0; translate: 0 8px; } }
  .dbt-oee-linesv { grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.25fr); }
  .dbt-oee-lossv { grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr); }
  .dbt-oee-panel { position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 10px; background: var(--dbt-oee-panel); box-shadow: inset 0 0 0 1px var(--dbt-oee-line); }
  .dbt-oee-ph { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 12px; padding: 12px 14px 8px; & h3 { font-size: 13px; font-weight: 650; } }
  .dbt-oee-hint { font: 11px var(--dbt-oee-mono); color: var(--dbt-oee-faint); }

  /* cards */
  .dbt-oee-cardcol { min-height: 0; display: flex; flex-direction: column; gap: 8px; }
  .dbt-oee-sortbar { display: flex; align-items: center; justify-content: space-between; }
  .dbt-oee-seg {
    display: inline-flex; gap: 2px; padding: 2px; border-radius: 7px; background: var(--dbt-oee-deep); box-shadow: inset 0 0 0 1px var(--dbt-oee-line);
    & button { padding: 3px 9px; border-radius: 5px; font-size: 11.5px; font-weight: 560; color: var(--dbt-oee-muted); }
    & button[aria-checked="true"] { background: var(--dbt-oee-raise); color: var(--dbt-oee-ink); }
  }
  .dbt-oee-cards { flex: 1; min-height: 0; overflow: auto; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); grid-auto-rows: minmax(132px, 1fr); gap: 8px; scrollbar-width: thin; scrollbar-color: var(--dbt-oee-line-2) transparent; padding: 2px; }
  .dbt-oee-card {
    position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: auto auto 1fr auto auto; gap: 2px 8px; padding: 10px 12px; border-radius: 10px; text-align: left;
    background: var(--dbt-oee-panel); box-shadow: inset 0 0 0 1px var(--dbt-oee-line); transition: background-color 160ms, box-shadow 160ms;
    animation: dbt-oee-in 520ms var(--dbt-oee-ease) both; animation-delay: calc(var(--i) * 55ms + 100ms);
    &:hover { background: var(--dbt-oee-raise); }
    &[aria-selected="true"] { background: var(--dbt-oee-raise); box-shadow: inset 0 0 0 1.5px var(--dbt-oee-accent); }
    & .dbt-oee-cname { font-weight: 650; font-size: 13px; }
    & .dbt-oee-cid { grid-column: 1; font: 10px var(--dbt-oee-mono); color: var(--dbt-oee-faint); letter-spacing: 0.06em; }
    & .dbt-oee-coee { grid-row: 1 / 3; grid-column: 2; text-align: right; font: 650 22px/1 system-ui, sans-serif; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
    & .dbt-oee-coee small { font-size: 11px; color: var(--dbt-oee-muted); font-weight: 500; }
    & .dbt-oee-apq { grid-column: 1 / -1; align-self: center; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
    & .dbt-oee-apq span { display: grid; gap: 3px; font: 10px var(--dbt-oee-mono); color: var(--dbt-oee-muted); }
    & .dbt-oee-apq b { color: var(--dbt-oee-ink); font-weight: 600; font-size: 11px; }
    & .dbt-oee-apq i { height: 3px; border-radius: 2px; background: linear-gradient(90deg, var(--dbt-oee-ink) var(--w), var(--dbt-oee-line) var(--w)); }
    & .dbt-oee-mini { grid-column: 1 / -1; display: flex; height: 8px; border-radius: 2px; overflow: hidden; gap: 1px; }
    & .dbt-oee-mini span { height: 100%; min-width: 1px; }
    & .dbt-oee-cstate { grid-column: 1 / -1; justify-self: end; margin-top: 4px; font: 600 9.5px var(--dbt-oee-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--dbt-oee-faint); }
  }
  .dbt-oee-card[data-band="hi"] .dbt-oee-coee { color: var(--dbt-oee-run); }
  .dbt-oee-card[data-band="lo"] .dbt-oee-coee { color: var(--dbt-oee-fault); }
  .dbt-oee-seg-run { background: var(--dbt-oee-run); }
  .dbt-oee-seg-minor { background: var(--dbt-oee-minor); }
  .dbt-oee-seg-change { background: var(--dbt-oee-change); }
  .dbt-oee-seg-fault { background: var(--dbt-oee-fault); }
  .dbt-oee-seg-break { background: repeating-linear-gradient(135deg, var(--dbt-oee-break) 0 2px, transparent 2px 4px); }
  .dbt-oee-seg-future { background: repeating-linear-gradient(90deg, var(--dbt-oee-line-2) 0 1px, transparent 1px 4px); }

  /* detail */
  .dbt-oee-detail { min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 10px; padding: 14px 16px; border-radius: 10px; background: var(--dbt-oee-panel); box-shadow: inset 0 0 0 1px var(--dbt-oee-line); scrollbar-width: thin; scrollbar-color: var(--dbt-oee-line-2) transparent; }
  .dbt-oee-dh {
    display: flex; justify-content: space-between; align-items: flex-start; gap: 12px;
    & h3 { font-size: 17px; font-weight: 700; letter-spacing: -0.015em; }
    & p { font: 11px var(--dbt-oee-mono); color: var(--dbt-oee-muted); }
  }
  .dbt-oee-dbig {
    text-align: right;
    & b { font: 700 30px/1 system-ui, sans-serif; letter-spacing: -0.04em; font-variant-numeric: tabular-nums; color: var(--dbt-oee-accent); }
    & small { margin-left: 4px; font-size: 11px; color: var(--dbt-oee-muted); }
    & p { margin-top: 4px; white-space: nowrap; }
  }
  .dbt-oee-block { display: grid; gap: 6px; }
  .dbt-oee-wf { position: relative; height: 168px; }
  .dbt-oee-wsvg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dbt-oee-wsvg text { font: 10px var(--dbt-oee-mono); fill: var(--dbt-oee-muted); font-variant-numeric: tabular-nums; }
  .dbt-oee-wsvg .dbt-oee-wv { fill: var(--dbt-oee-ink); font-weight: 600; }
  .dbt-oee-wbar { transform-box: fill-box; transform-origin: 50% 100%; animation: dbt-oee-grow 620ms var(--dbt-oee-ease) both; animation-delay: calc(var(--i) * 60ms); transition: opacity 200ms; }
  .dbt-oee-hit { fill: transparent; }
  .dbt-oee-wr { fill: color-mix(in srgb, var(--dbt-oee-ink) 34%, var(--dbt-oee-panel)); }
  .dbt-oee-wbar[data-k="total"] .dbt-oee-wr { fill: color-mix(in srgb, var(--dbt-oee-ink) 72%, var(--dbt-oee-panel)); }
  .dbt-oee-wbar[data-k="final"] .dbt-oee-wr { fill: var(--dbt-oee-accent); }
  .dbt-oee-wbar[data-cat="fault"] .dbt-oee-wr { fill: var(--dbt-oee-fault); }
  .dbt-oee-wbar[data-cat="change"] .dbt-oee-wr { fill: var(--dbt-oee-change); }
  .dbt-oee-wbar[data-cat="minor"] .dbt-oee-wr { fill: var(--dbt-oee-minor); }
  .dbt-oee-wbar[data-cat="speed"] .dbt-oee-wr { fill: color-mix(in srgb, var(--dbt-oee-minor) 50%, var(--dbt-oee-panel)); }
  .dbt-oee-wbar[data-cat="reject"] .dbt-oee-wr { fill: color-mix(in srgb, var(--dbt-oee-fault) 50%, var(--dbt-oee-panel)); }
  .dbt-oee-wsvg:has(.dbt-oee-wbar:hover) .dbt-oee-wbar:not(:hover), .dbt-oee-wf[data-hl] .dbt-oee-wbar:not([data-on]) { opacity: 0.35; }
  .dbt-oee-wsvg .dbt-oee-conn { stroke: var(--dbt-oee-line-2); stroke-dasharray: 2 2; }
  .dbt-oee-wsvg .dbt-oee-axl { stroke: var(--dbt-oee-line); }

  .dbt-oee-tl { position: relative; display: grid; gap: 4px; padding: 2px 0; border-radius: 6px; }
  .dbt-oee-strip { position: relative; height: 34px; border-radius: 4px; overflow: hidden; background: var(--dbt-oee-deep); animation: dbt-oee-wipe 900ms var(--dbt-oee-ease) both 120ms; }
  .dbt-oee-strip span { position: absolute; top: 0; bottom: 0; left: calc(var(--x) * 1%); width: max(1px, calc(var(--w) * 1%)); transition: opacity 200ms, transform 200ms var(--dbt-oee-ease); }
  .dbt-oee-strip span[data-cat="minor"] { top: 7px; bottom: 7px; }
  .dbt-oee-strip span[data-cur] { box-shadow: inset 0 0 0 2px var(--dbt-oee-ink); }
  .dbt-oee-tl[data-hl] .dbt-oee-strip span:not([data-on]) { opacity: 0.15; }
  .dbt-oee-strip span:hover { transform: scaleY(1.08); }
  .dbt-oee-ticks { position: relative; height: 14px; font: 9.5px var(--dbt-oee-mono); color: var(--dbt-oee-faint); & span { position: absolute; left: calc(var(--x) * 1%); translate: -50% 0; white-space: nowrap; } & span:first-child { translate: 0 0; } }
  .dbt-oee-ticks span[data-now] { color: var(--dbt-oee-accent); }

  .dbt-oee-reasons { display: grid; gap: 6px; }
  .dbt-oee-reason {
    display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 3px 10px; align-items: baseline; font-size: 12px;
    animation: dbt-oee-in 420ms var(--dbt-oee-ease) both; animation-delay: calc(var(--i) * 50ms + 200ms);
