  { id: 'L3', name: 'CNC Cell A', kind: 'cnc', meta: '2 × 5-axis mills · housing HS-40', ideal: 48, base: 0.66 },
  { id: 'L4', name: 'CNC Cell B', kind: 'cnc', meta: '3 lathes · shaft SF-12', ideal: 52, base: 0.71 },
  { id: 'L5', name: 'Assembly 1', kind: 'asm', meta: '4 stations + 2 robots · actuator AC-7', ideal: 18, base: 0.78 },
  { id: 'L6', name: 'Coating', kind: 'coat', meta: 'powder line · 6 m/min · 2 booths', ideal: 6, base: 0.72 }
];
const REASONS = {
  press: { fault: ['Die feed jam', 'Hydraulic pressure low', 'Transfer finger fault'], change: 'Die change', minor: ['Strip misfeed', 'Light curtain trip', 'Coil end'], co: [24, 38], nco: 1, startRej: 40, rejRate: 0.008, sf: [0.86, 0.93] },
  cnc: { fault: ['Spindle overload', 'Tool breakage', 'Coolant pump fault'], change: 'Fixture change', minor: ['Probe retry', 'Chip clearing', 'Door interlock'], co: [32, 50], nco: 1, startRej: 1, rejRate: 0.015, sf: [0.9, 0.97] },
  asm: { fault: ['Screw feeder fault', 'Vision reject loop'], change: 'Variant change', minor: ['Part shortage', 'Torque retry', 'Label printer'], co: [12, 18], nco: 2, startRej: 3, rejRate: 0.006, sf: [0.88, 0.95] },
  coat: { fault: ['Oven temperature drift', 'Conveyor stop'], change: 'Colour change', minor: ['Hanger jam', 'Spray gun clog'], co: [18, 26], nco: 2, startRej: 12, rejRate: 0.022, sf: [0.9, 0.96] }
};
const SHIFTS = { C: { name: 'Night', start: 22 * 60, off: 0 }, A: { name: 'Early', start: 6 * 60, off: 480 }, B: { name: 'Late', start: 14 * 60, off: 960 } };
const NOW = 264; // minutes into the Late shift
const BREAK = [270, 300];
const SCRIPT = { // a few hand-placed events so the day has a story
  'L2B': [{ a: 95, d: 46, cat: 'fault', reason: 'Hydraulic pressure low' }],
  'L4A': [{ a: 30, d: 58, cat: 'change', reason: 'Fixture change' }],
  'L6C': [{ a: 180, d: 28, cat: 'fault', reason: 'Oven temperature drift' }],
