}
const DATA = {};
LINES.forEach((L) => { DATA[L.id] = {}; ['C', 'A', 'B'].forEach((sk) => { DATA[L.id][sk] = genShift(L, sk); }); });
LINES.forEach((L) => { // "Day so far" aggregates the three shifts on one 24 h axis
  const parts = ['C', 'A', 'B'].map((sk) => DATA[L.id][sk]), agg = { sk: 'D', E: 960 + NOW, len: 1440, live: true, segs: [], ev: [] };
