const ratio = (x) => ({ oee: x.FP / x.P, a: x.Run / x.P, p: x.Net / x.Run, q: x.good / x.total });
const shiftStart = (sk) => (sk === 'D' ? SHIFTS.C.start : SHIFTS[sk].start);
