  htip.style.translate = `${x}px ${y}px`; htip.setAttribute('data-on', '');
}
function openCell(cell) {
  const ri = +cell.dataset.r, c = HIST[ri].cells[+cell.dataset.c]; if (!c.today) return;
  st.line = HIST[ri].L.id; setShift(c.sk); setView('lines');
}
hgrid.addEventListener('pointerover', (e) => { const c = e.target.closest('.dbt-oee-hcell'); if (c) heatTip(c); });
hgrid.addEventListener('pointerleave', () => htip.removeAttribute('data-on'));
hgrid.addEventListener('click', (e) => { const c = e.target.closest('.dbt-oee-hcell'); if (c) openCell(c); });
hgrid.addEventListener('keydown', (e) => {
  const m = { ArrowRight: [0, 1], ArrowLeft: [0, -1], ArrowDown: [1, 0], ArrowUp: [-1, 0] }[e.key];
  const cur = () => $(`.dbt-oee-hcell[data-r="${hfocus.r}"][data-c="${hfocus.c}"]`, hgrid);
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); const c = cur(); if (c) openCell(c); return; }
  if (e.key === 'Escape') { $$('[data-focus]', hgrid).forEach((x) => x.removeAttribute('data-focus')); htip.removeAttribute('data-on'); return; }
  if (!m) return;
  e.preventDefault();
  hfocus = { r: clamp(hfocus.r + m[0], 0, HIST.length - 1), c: clamp(hfocus.c + m[1], 0, 20) };
  $$('[data-focus]', hgrid).forEach((x) => x.removeAttribute('data-focus'));
  const c = cur(); c.setAttribute('data-focus', ''); c.scrollIntoView({ block: 'nearest', inline: 'nearest' }); heatTip(c);
});
hgrid.addEventListener('focus', () => { const c = $(`.dbt-oee-hcell[data-r="${hfocus.r}"][data-c="${hfocus.c}"]`, hgrid); if (c) { c.setAttribute('data-focus', ''); heatTip(c); } });
hgrid.addEventListener('blur', () => { $$('[data-focus]', hgrid).forEach((x) => x.removeAttribute('data-focus')); htip.removeAttribute('data-on'); });

/* ---------- shift + views ---------- */
const sbtns = $$('.dbt-oee-shifts button');
function setShift(sk, focus) {
  st.shift = sk;
  sbtns.forEach((b) => { const on = b.dataset.shift === sk; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
  renderKpis(); renderCards(false); renderDetail(true);
  if (st.view === 'losses') { drawPareto(true); renderEvents(); }
}
$('.dbt-oee-shifts').addEventListener('click', (e) => { const b = e.target.closest('button'); if (b && b.dataset.shift !== st.shift) setShift(b.dataset.shift); });
$('.dbt-oee-shifts').addEventListener('keydown', (e) => {
  const d = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key]; if (!d) return;
  e.preventDefault(); const i = sbtns.findIndex((b) => b.dataset.shift === st.shift); setShift(sbtns[(i + d + sbtns.length) % sbtns.length].dataset.shift, true);
});
const TITLES = { lines: 'Line performance', losses: 'Where time is lost', history: 'Seven-day history' };
const tabs = $$('.dbt-oee-navbtn');
function setView(v, focus) {
  st.view = v;
  tabs.forEach((b) => { const on = b.dataset.view === v; b.setAttribute('aria-selected', String(on)); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
  $$('.dbt-oee-view').forEach((s) => { s.hidden = s.dataset.view !== v; });
  $('[data-title]').textContent = TITLES[v];
  requestAnimationFrame(() => {
    if (v === 'lines') { renderCards(false); renderDetail(true); }
    if (v === 'losses') { drawPareto(true); renderEvents(); }
    if (v === 'history') renderHeat();
  });
}
$('.dbt-oee-nav').addEventListener('click', (e) => { const b = e.target.closest('.dbt-oee-navbtn'); if (b && b.dataset.view !== st.view) setView(b.dataset.view); });
$('.dbt-oee-nav').addEventListener('keydown', (e) => {
  const d = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key]; if (!d) return;
  e.preventDefault(); const i = tabs.findIndex((b) => b.dataset.view === st.view); setView(tabs[(i + d + tabs.length) % tabs.length].dataset.view, true);
});

let sz = '';
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const k = `${wf.clientWidth}x${wf.clientHeight}|${pplot.clientWidth}x${pplot.clientHeight}`;
  if (k === sz) return; sz = k;
  if (st.view === 'lines') drawWaterfall(DATA[st.line][st.shift], false);
  if (st.view === 'losses') drawPareto(false);
});
ro.observe(wf); ro.observe(pplot);
renderKpis(); renderCards(false); renderDetail(true);

css:
@keyframes dbt-hvac-pulse { 0% { r: 4; opacity: 0.8; } 100% { r: 13; opacity: 0; } }
@keyframes dbt-hvac-in { from { opacity: 0; translate: 0 8px; } }
@keyframes dbt-hvac-zin { from { opacity: 0; } }
@keyframes dbt-hvac-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }

.dbt-hvac {
  /* re-theme: paper, ink, accent; the three ramps derive from cool / warm / occupancy */
  --dbt-hvac-bg: oklch(0.972 0.005 240);
  --dbt-hvac-ink: oklch(0.27 0.03 260);
  --dbt-hvac-accent: oklch(0.47 0.09 200);
  --dbt-hvac-cool: oklch(0.62 0.13 245);
  --dbt-hvac-warm: oklch(0.64 0.18 35);
  --dbt-hvac-good: oklch(0.82 0.11 155);
  --dbt-hvac-mid: oklch(0.86 0.13 88);
  --dbt-hvac-bad: oklch(0.66 0.18 30);
  --dbt-hvac-occ: oklch(0.5 0.1 200);
  --dbt-hvac-neutral: color-mix(in oklch, var(--dbt-hvac-bg), white 50%);
  --dbt-hvac-panel: color-mix(in oklch, var(--dbt-hvac-bg), white 70%);
  --dbt-hvac-side-bg: color-mix(in oklch, var(--dbt-hvac-bg), var(--dbt-hvac-ink) 4%);
  --dbt-hvac-line: color-mix(in oklch, var(--dbt-hvac-ink) 11%, transparent);
  --dbt-hvac-line-2: color-mix(in oklch, var(--dbt-hvac-ink) 20%, transparent);
  --dbt-hvac-muted: color-mix(in oklch, var(--dbt-hvac-ink) 62%, var(--dbt-hvac-bg));
  --dbt-hvac-faint: color-mix(in oklch, var(--dbt-hvac-ink) 40%, var(--dbt-hvac-bg));
  --dbt-hvac-hover: color-mix(in oklch, var(--dbt-hvac-ink) 5%, transparent);
  --dbt-hvac-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dbt-hvac-spring: linear(0, 0.013, 0.05 2.4%, 0.2 5.3%, 0.81 14%, 0.99 18%, 1.07 21.6%, 1.08 25%, 1.05 30%, 1.007 37.5%, 0.994 45%, 1);
  --dbt-hvac-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbt-hvac-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbt-hvac-bg);
  color: var(--dbt-hvac-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light;
  accent-color: var(--dbt-hvac-accent);
  box-shadow: inset 0 0 0 1px var(--dbt-hvac-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbt-hvac-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ol, & ul { list-style: none; margin: 0; padding: 0; }
  & dl, & dd { margin: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbt-hvac-eyebrow { font: 600 10px/1.3 var(--dbt-hvac-mono); letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbt-hvac-muted); }

  .dbt-hvac-app { display: grid; height: 100%; grid-template-columns: 200px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side head" "side main"; }

  /* ---------- side ---------- */
  .dbt-hvac-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 20px; padding: 18px 12px 16px; background: var(--dbt-hvac-side-bg); border-right: 1px solid var(--dbt-hvac-line); }
  .dbt-hvac-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbt-hvac-brand svg { width: 32px; height: 32px; flex: none; padding: 5px; border-radius: 9px; background: var(--dbt-hvac-ink); fill: none; stroke: var(--dbt-hvac-bg); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbt-hvac-brand span { display: grid; line-height: 1.2; min-width: 0; }
  .dbt-hvac-brand b { font-weight: 700; letter-spacing: -0.01em; }
  .dbt-hvac-brand small { font-size: 11px; color: var(--dbt-hvac-muted); white-space: nowrap; }
  .dbt-hvac-nav { display: grid; gap: 2px; }
  .dbt-hvac-navbtn {
    position: relative; display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px 10px; border-radius: 8px; color: var(--dbt-hvac-muted); font-weight: 560;
    transition: color 160ms, background-color 160ms;
    & svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
    &:hover { color: var(--dbt-hvac-ink); background: var(--dbt-hvac-hover); }
    &[aria-selected="true"] { color: var(--dbt-hvac-ink); background: var(--dbt-hvac-panel); box-shadow: 0 0 0 1px var(--dbt-hvac-line), 0 1px 2px color-mix(in oklch, var(--dbt-hvac-ink) 8%, transparent); }
    &[aria-selected="true"] svg { color: var(--dbt-hvac-accent); }
  }
  .dbt-hvac-badge { margin-left: auto; min-width: 20px; padding: 0 6px; border-radius: 99px; font: 650 10.5px/18px var(--dbt-hvac-mono); font-style: normal; text-align: center; background: var(--dbt-hvac-warm); color: white; }
  .dbt-hvac-badge[data-zero] { background: var(--dbt-hvac-line); color: var(--dbt-hvac-muted); }
  .dbt-hvac-section { display: grid; gap: 8px; padding: 0 4px; }
  .dbt-hvac-floors { display: grid; gap: 0; padding: 14px 6px 0; position: relative; }
  .dbt-hvac-floors::before { content: ""; position: absolute; left: 6px; right: 6px; top: 2px; height: 13px; background: var(--dbt-hvac-line-2); clip-path: polygon(0 100%, 50% 0, 100% 100%); }
  .dbt-hvac-floor {
    display: grid; grid-template-columns: auto minmax(0, 1fr) auto; grid-template-areas: "lvl t badge" "lvl p badge"; align-items: center; gap: 0 10px; padding: 8px 10px; text-align: left;
    & b { grid-area: lvl; } & .dbt-hvac-ft { grid-area: t; color: var(--dbt-hvac-ink) !important; font-weight: 600; } & .dbt-hvac-fp { grid-area: p; } & em { grid-area: badge; }
    border: 1px solid var(--dbt-hvac-line-2); border-top-width: 0; background: var(--dbt-hvac-panel); transition: background-color 160ms, box-shadow 160ms;
    &:first-child { border-top-width: 1px; }
    & b { font: 700 12px var(--dbt-hvac-mono); }
    & span { font-size: 11.5px; color: var(--dbt-hvac-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & em { font: 650 10px/16px var(--dbt-hvac-mono); font-style: normal; min-width: 18px; text-align: center; border-radius: 9px; padding: 0 5px; background: color-mix(in oklch, var(--dbt-hvac-warm) 16%, transparent); color: color-mix(in oklch, var(--dbt-hvac-warm), var(--dbt-hvac-ink) 30%); }
    & em[data-zero] { background: none; color: var(--dbt-hvac-faint); }
    &:hover { background: color-mix(in oklch, var(--dbt-hvac-panel), var(--dbt-hvac-ink) 3%); }
    &[aria-checked="true"] { background: color-mix(in oklch, var(--dbt-hvac-accent) 11%, var(--dbt-hvac-panel)); box-shadow: inset 3px 0 0 var(--dbt-hvac-accent); }
  }
  .dbt-hvac-floors::after { content: ""; display: block; height: 6px; margin: 0 -6px; border-top: 2px solid var(--dbt-hvac-ink); background: repeating-linear-gradient(135deg, var(--dbt-hvac-line-2) 0 1px, transparent 1px 5px); }
  .dbt-hvac-out { margin-top: auto; display: flex; align-items: center; gap: 10px; padding: 12px 8px 0; border-top: 1px solid var(--dbt-hvac-line); }
  .dbt-hvac-out svg { width: 22px; height: 22px; flex: none; fill: none; stroke: var(--dbt-hvac-muted); stroke-width: 1.6; stroke-linecap: round; }
  .dbt-hvac-out span { display: grid; line-height: 1.25; } .dbt-hvac-out b { font: 650 15px var(--dbt-hvac-mono); } .dbt-hvac-out small { font-size: 11px; color: var(--dbt-hvac-muted); }

  /* ---------- head ---------- */
  .dbt-hvac-head { grid-area: head; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px 24px; padding: 16px 20px 14px; min-width: 0; }
  .dbt-hvac-titles { display: grid; gap: 4px; }
  .dbt-hvac-h { font-size: clamp(20px, 2.3cqi, 27px); font-weight: 680; letter-spacing: -0.025em; line-height: 1.05; }
  .dbt-hvac-kpis {
    display: flex; flex-wrap: wrap;
    & div { padding: 0 14px; border-left: 1px solid var(--dbt-hvac-line); }
    & div:first-child { border-left: 0; padding-left: 0; }
    & div:last-child { padding-right: 0; }
    & dt { font-size: 11px; color: var(--dbt-hvac-muted); font-weight: 560; white-space: nowrap; }
    & dd { display: flex; align-items: baseline; gap: 3px; white-space: nowrap; }
    & b { font-size: clamp(18px, 2cqi, 23px); font-weight: 650; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
    & small { font-size: 11px; color: var(--dbt-hvac-muted); }
  }
  .dbt-hvac-kpis:has([data-k="out"]:not([data-zero])) div:nth-child(2) b { color: var(--dbt-hvac-warm); }

  /* ---------- main ---------- */
  .dbt-hvac-main { grid-area: main; min-height: 0; min-width: 0; display: grid; padding: 0 20px 18px; }
  .dbt-hvac-view { min-height: 0; min-width: 0; display: grid; gap: 14px; transition: opacity 320ms var(--dbt-hvac-ease), translate 420ms var(--dbt-hvac-ease); @starting-style { opacity: 0; translate: 0 8px; } }
  .dbt-hvac-planv { grid-template-columns: minmax(0, 1fr) 318px; }
  .dbt-hvac-panel { position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dbt-hvac-panel); box-shadow: 0 0 0 1px var(--dbt-hvac-line), 0 1px 3px color-mix(in oklch, var(--dbt-hvac-ink) 5%, transparent); }
  .dbt-hvac-ph { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 14px; padding: 12px 14px 8px; & h3 { font-size: 13px; font-weight: 650; } }

  .dbt-hvac-layers, .dbt-hvac-ftabs, .dbt-hvac-modes {
    display: inline-flex; gap: 2px; padding: 3px; border-radius: 9px; background: var(--dbt-hvac-side-bg); box-shadow: inset 0 0 0 1px var(--dbt-hvac-line);
    & button { padding: 4px 10px; border-radius: 6px; font-size: 12px; font-weight: 560; color: var(--dbt-hvac-muted); transition: color 160ms, background-color 160ms, box-shadow 160ms; }
    & button:hover { color: var(--dbt-hvac-ink); }
    & button[aria-checked="true"] { background: var(--dbt-hvac-panel); color: var(--dbt-hvac-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbt-hvac-ink) 14%, transparent), 0 0 0 1px var(--dbt-hvac-line); }
  }
  .dbt-hvac-ftabs { display: none; & button { font-family: var(--dbt-hvac-mono); font-weight: 650; } }
  .dbt-hvac-ramp {
    display: flex; align-items: center; gap: 6px; font: 10px var(--dbt-hvac-mono); color: var(--dbt-hvac-muted); margin-left: auto;
    & i { width: 110px; height: 8px; border-radius: 4px; background: linear-gradient(90deg in oklab, var(--dbt-hvac-cool), var(--dbt-hvac-neutral), var(--dbt-hvac-warm)); box-shadow: inset 0 0 0 1px var(--dbt-hvac-line); }
  }
  .dbt-hvac-planp:has([data-layer="co2"][aria-checked="true"]) .dbt-hvac-ramp i { background: linear-gradient(90deg in oklab, var(--dbt-hvac-good), var(--dbt-hvac-mid), var(--dbt-hvac-bad)); }
  .dbt-hvac-planp:has([data-layer="occ"][aria-checked="true"]) .dbt-hvac-ramp i { background: linear-gradient(90deg in oklab, var(--dbt-hvac-neutral), var(--dbt-hvac-occ)); }

  /* plan */
  .dbt-hvac-planwrap {
    position: relative; flex: 1; min-height: 0; margin: 0 12px 12px; border-radius: 10px; overflow: hidden;
    background: radial-gradient(circle, var(--dbt-hvac-line-2) 0.8px, transparent 1px) 0 0 / 16px 16px, var(--dbt-hvac-bg);
  }
  .dbt-hvac-plan { position: absolute; inset: 0; width: 100%; height: 100%; outline: none; }
  .dbt-hvac-plan text { pointer-events: none; font-family: system-ui, sans-serif; }
  .dbt-hvac-zone { cursor: pointer; outline: none; animation: dbt-hvac-zin 500ms var(--dbt-hvac-ease) both; animation-delay: calc(var(--i) * 35ms); }
  .dbt-hvac-zr {
    --dc: clamp(0, var(--d) / -2, 1); --dw: clamp(0, var(--d) / 2, 1);
    --cq: clamp(0, (var(--c) - 400) / 1000, 1);
    fill: color-mix(in oklab, var(--dbt-hvac-cool) calc(var(--dc) * 88%), color-mix(in oklab, var(--dbt-hvac-warm) calc(var(--dw) * 88%), var(--dbt-hvac-neutral)));
    stroke: var(--dbt-hvac-ink); stroke-width: 1.4; stroke-opacity: 0.55;
    transition: fill 600ms var(--dbt-hvac-ease), opacity 200ms;
  }
  .dbt-hvac-plan[data-layer="co2"] .dbt-hvac-zr { fill: color-mix(in oklab, color-mix(in oklab, var(--dbt-hvac-good), var(--dbt-hvac-mid) calc(min(var(--cq) * 2, 1) * 100%)), var(--dbt-hvac-bad) calc(max(var(--cq) * 2 - 1, 0) * 100%)); }
  .dbt-hvac-plan[data-layer="occ"] .dbt-hvac-zr { fill: color-mix(in oklab, var(--dbt-hvac-occ) calc(var(--o) * 85%), var(--dbt-hvac-neutral)); }
  .dbt-hvac-plan:has(.dbt-hvac-zone:hover) .dbt-hvac-zone:not(:hover) .dbt-hvac-zr { opacity: 0.5; }
  .dbt-hvac-zone:focus-visible .dbt-hvac-zr { stroke: var(--dbt-hvac-accent); stroke-width: 3; stroke-opacity: 1; }
  .dbt-hvac-zn { font-size: 10px; font-weight: 600; letter-spacing: 0.03em; fill: color-mix(in oklch, var(--dbt-hvac-ink) 80%, transparent); }
  .dbt-hvac-zv { font: 650 15px var(--dbt-hvac-mono); fill: var(--dbt-hvac-ink); font-variant-numeric: tabular-nums; transition: opacity 300ms; opacity: 0; }
  .dbt-hvac-plan[data-layer="temp"] .dbt-hvac-zv[data-l="temp"], .dbt-hvac-plan[data-layer="co2"] .dbt-hvac-zv[data-l="co2"], .dbt-hvac-plan[data-layer="occ"] .dbt-hvac-zv[data-l="occ"] { opacity: 1; }
  .dbt-hvac-plan[data-layer="occ"] .dbt-hvac-zone[data-dark] text { fill: white; }
  .dbt-hvac-core { stroke: var(--dbt-hvac-ink); stroke-width: 1.4; stroke-opacity: 0.55; }
  .dbt-hvac-corel { font-size: 9.5px; font-weight: 700; letter-spacing: 0.14em; fill: var(--dbt-hvac-faint); }
  .dbt-hvac-shell { fill: none; stroke: var(--dbt-hvac-ink); stroke-width: 5; stroke-linejoin: round; }
  .dbt-hvac-win { stroke: color-mix(in oklch, var(--dbt-hvac-cool) 55%, white); stroke-width: 5; }
  .dbt-hvac-alert { fill: var(--dbt-hvac-warm); }
  .dbt-hvac-alert-ring { fill: none; stroke: var(--dbt-hvac-warm); stroke-width: 1.5; animation: dbt-hvac-pulse 1.6s cubic-bezier(0.2, 0.7, 0.3, 1) infinite; }
  .dbt-hvac-alert[data-cold], .dbt-hvac-alert-ring[data-cold] { fill: var(--dbt-hvac-cool); stroke: var(--dbt-hvac-cool); }
  .dbt-hvac-alert-ring[data-cold] { fill: none; }
  .dbt-hvac-selbox { fill: none; stroke: var(--dbt-hvac-ink); stroke-width: 3.5; pointer-events: none; transition: x 380ms var(--dbt-hvac-spring), y 380ms var(--dbt-hvac-spring), width 380ms var(--dbt-hvac-spring), height 380ms var(--dbt-hvac-spring); }

  .dbt-hvac-alerts { display: grid; gap: 2px; padding: 0 12px 12px; max-height: 40%; overflow: auto; scrollbar-width: thin; }
  .dbt-hvac-al {
    display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; align-items: center; gap: 0 10px; padding: 6px 8px; border-radius: 8px; cursor: pointer; text-align: left; width: 100%;
    animation: dbt-hvac-in 420ms var(--dbt-hvac-ease) both; animation-delay: calc(var(--i) * 60ms + 150ms); transition: background-color 140ms;
    & > i { width: 8px; height: 8px; border-radius: 50%; background: var(--dbt-hvac-warm); }
    &[data-k="cool"] > i { background: var(--dbt-hvac-cool); }
    &[data-k="co2"] > i { background: var(--dbt-hvac-bad); border-radius: 2px; }
