let lastW = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (chart.clientWidth && chart.clientWidth !== lastW) { lastW = chart.clientWidth; if (st.view === 'plan') renderDetail(false); }
});
