  }
  @container (max-width: 760px) {
    .dbt-anomaly-app { display: flex; flex-direction: column; overflow: auto; scrollbar-width: thin; }
    .dbt-anomaly-side { position: sticky; top: 0; z-index: 6; flex: none; flex-direction: row; justify-content: space-between; align-items: center; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dbt-anomaly-line); }
