    .dbt-anomaly-list { max-height: 320px; }
    .dbt-anomaly-charts { display: flex; flex-direction: column; }
    .dbt-anomaly-focusp { height: 380px; flex: none; }
    .dbt-anomaly-eventsp { height: 240px; flex: none; }
    .dbt-anomaly-fleetv { overflow: visible; }
  }
  @container (max-width: 440px) {
    .dbt-anomaly-keys { display: none; }
    .dbt-anomaly-focusp { height: 340px; }
    .dbt-anomaly-table th:nth-child(2), .dbt-anomaly-table td:nth-child(2) { display: none; }
  }

