    .dbt-anomaly-tile, .dbt-anomaly-table tbody tr, .dbt-anomaly-badge[data-pop] { animation: none; }
    .dbt-anomaly-view, .dbt-anomaly-tip, .dbt-anomaly-tile, .dbt-anomaly-hl { transition: none; }
    .dbt-anomaly-tile:hover { translate: none; }
  }
}

