const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
let seed = 0x5e4a11;
const rnd = () => { seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const gauss = () => { let u = 0, v = 0; while (!u) u = rnd(); while (!v) v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };

/* ---------- 7 days of 5-minute samples, 12 channels on 3 turbines ---------- */
const N = 2016, T0 = Date.UTC(2026, 8, 23, 14, 25);
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const at = (i) => new Date(T0 + i * 300000);
const hm = (d) => `${String(d.getUTCHours()).padStart(2, '0')}:${String(d.getUTCMinutes()).padStart(2, '0')}`;
const stamp = (i) => { const d = at(i); return `${WD[d.getUTCDay()]} ${d.getUTCDate()} · ${hm(d)}`; };
const hourOf = (i) => { const d = at(i); return d.getUTCHours() + d.getUTCMinutes() / 60; };
