@property --dbt-charge-soc { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --dbt-charge-soci { syntax: "<integer>"; inherits: true; initial-value: 0; }
@property --dbt-charge-a { syntax: "<number>"; inherits: false; initial-value: 0; }
@property --dbt-charge-b { syntax: "<number>"; inherits: false; initial-value: 0; }
@property --dbt-charge-c { syntax: "<number>"; inherits: true; initial-value: 100; }
@keyframes dbt-charge-in { from { opacity: 0; translate: 0 10px; } }
@keyframes dbt-charge-cell { from { opacity: 0; scale: 0.4; } }
@keyframes dbt-charge-blink { 50% { opacity: 0.25; } }
@keyframes dbt-charge-flow { from { translate: -14px 0; } to { translate: 0 0; } }
@keyframes dbt-charge-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbt-charge-ping { 0% { scale: 1; opacity: 0.7; } 100% { scale: 2.6; opacity: 0; } }

.dbt-charge {
  /* re-theme: background, ink, volt (charging) — hold, fault and the throttle stripe derive from these */
  --dbt-charge-bg: oklch(0.175 0.006 95);
  --dbt-charge-ink: oklch(0.95 0.012 105);
  --dbt-charge-volt: oklch(0.9 0.19 124);
  --dbt-charge-hold: oklch(0.8 0.13 70);
  --dbt-charge-fault: oklch(0.68 0.19 30);
  --dbt-charge-wd: var(--dbt-charge-volt);
  --dbt-charge-we: oklch(0.78 0.09 250);
  --dbt-charge-panel: color-mix(in oklch, var(--dbt-charge-bg), white 4%);
  --dbt-charge-raise: color-mix(in oklch, var(--dbt-charge-bg), white 8.5%);
  --dbt-charge-deep: color-mix(in oklch, var(--dbt-charge-bg), black 32%);
  --dbt-charge-line: color-mix(in oklch, var(--dbt-charge-ink) 9%, transparent);
  --dbt-charge-line-2: color-mix(in oklch, var(--dbt-charge-ink) 17%, transparent);
  --dbt-charge-muted: color-mix(in oklch, var(--dbt-charge-ink) 60%, var(--dbt-charge-bg));
  --dbt-charge-faint: color-mix(in oklch, var(--dbt-charge-ink) 38%, var(--dbt-charge-bg));
  --dbt-charge-volt-dim: color-mix(in oklch, var(--dbt-charge-volt) 22%, var(--dbt-charge-panel));
  --dbt-charge-stripe: repeating-linear-gradient(-45deg, var(--dbt-charge-volt) 0 3px, color-mix(in oklch, var(--dbt-charge-volt) 35%, var(--dbt-charge-bg)) 3px 7px);
  --dbt-charge-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dbt-charge-spring: linear(0, 0.013, 0.05 2.4%, 0.2 5.3%, 0.81 14%, 0.99 18%, 1.07 21.6%, 1.08 25%, 1.05 30%, 1.007 37.5%, 0.994 45%, 1);
  --dbt-charge-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbt-charge-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background:
    radial-gradient(90% 60% at 100% 0%, color-mix(in oklch, var(--dbt-charge-volt) 6%, transparent), transparent 60%),
    var(--dbt-charge-bg);
  color: var(--dbt-charge-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark;
  accent-color: var(--dbt-charge-volt);
  box-shadow: inset 0 0 0 1px var(--dbt-charge-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbt-charge-volt); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & dl, & dd { margin: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbt-charge-eyebrow { font: 600 10px/1.3 var(--dbt-charge-mono); letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbt-charge-muted); }
  .dbt-charge-app { display: grid; height: 100%; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "top" "kpis" "main"; }

  /* ---------- top bar ---------- */
  .dbt-charge-top { grid-area: top; display: flex; align-items: center; gap: 18px; padding: 12px 18px; border-bottom: 1px solid var(--dbt-charge-line); }
  .dbt-charge-brand {
    display: flex; align-items: center; gap: 10px; min-width: 0;
    & svg { width: 32px; height: 32px; flex: none; padding: 6px; border-radius: 9px; background: var(--dbt-charge-volt); fill: var(--dbt-charge-bg); stroke: var(--dbt-charge-bg); stroke-width: 1.2; stroke-linejoin: round; }
    & span { display: grid; line-height: 1.2; }
    & b { font-size: 14px; font-weight: 720; letter-spacing: -0.01em; }
    & small { font-size: 11px; color: var(--dbt-charge-muted); white-space: nowrap; }
  }
  .dbt-charge-tabs { position: relative; display: flex; gap: 2px; margin-inline: auto; padding: 3px; border-radius: 10px; background: var(--dbt-charge-deep); box-shadow: inset 0 0 0 1px var(--dbt-charge-line); }
  .dbt-charge-tab {
    position: relative; z-index: 1; display: flex; align-items: center; gap: 7px; padding: 6px 13px; border-radius: 7px; font-weight: 560; color: var(--dbt-charge-muted); transition: color 180ms;
    & svg { width: 17px; height: 17px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
    &:hover { color: var(--dbt-charge-ink); }
    &[aria-selected="true"] { color: var(--dbt-charge-ink); }
    &[aria-selected="true"] svg { color: var(--dbt-charge-volt); }
  }
  .dbt-charge-tabink {
    position: absolute; z-index: 0; top: 3px; bottom: 3px; left: 0; width: var(--w, 80px); border-radius: 7px; background: var(--dbt-charge-raise);
    box-shadow: inset 0 0 0 1px var(--dbt-charge-line-2), inset 0 -2px 0 var(--dbt-charge-volt);
    translate: var(--x, 3px) 0; transition: translate 520ms var(--dbt-charge-spring), width 520ms var(--dbt-charge-spring);
  }
  .dbt-charge-feed { display: flex; align-items: center; gap: 10px; }
  .dbt-charge-pause {
    display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--dbt-charge-muted); box-shadow: inset 0 0 0 1px var(--dbt-charge-line-2); transition: color 160ms, background-color 160ms;
    & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
    & .dbt-charge-ir { display: none; fill: currentColor; stroke-width: 1.2; }
    &:hover { color: var(--dbt-charge-ink); background: var(--dbt-charge-panel); }
    &[aria-pressed="true"] { color: var(--dbt-charge-hold); & .dbt-charge-ip { display: none; } & .dbt-charge-ir { display: block; } }
  }
  .dbt-charge-clock {
    display: grid; grid-template-columns: auto auto; align-items: center; column-gap: 7px; line-height: 1.15;
    & i { grid-row: 1 / 3; width: 8px; height: 8px; border-radius: 50%; background: var(--dbt-charge-volt); box-shadow: 0 0 0 3px color-mix(in oklch, var(--dbt-charge-volt) 20%, transparent); animation: dbt-charge-blink 1.6s steps(2, jump-none) infinite; }
    & b { font: 600 15px var(--dbt-charge-mono); font-variant-numeric: tabular-nums; letter-spacing: -0.02em; }
    & small { font: 10px var(--dbt-charge-mono); color: var(--dbt-charge-faint); letter-spacing: 0.06em; text-transform: uppercase; }
  }
  &:has(.dbt-charge-pause[aria-pressed="true"]) .dbt-charge-clock i { animation: none; background: var(--dbt-charge-hold); box-shadow: 0 0 0 3px color-mix(in oklch, var(--dbt-charge-hold) 20%, transparent); }

  /* ---------- KPIs ---------- */
  .dbt-charge-kpis { grid-area: kpis; display: grid; grid-template-columns: 1.25fr repeat(4, minmax(0, 1fr)); gap: 8px; padding: 12px 18px 12px; }
  .dbt-charge-kpi {
    min-width: 0; padding: 8px 12px 9px; border-radius: 10px; background: var(--dbt-charge-panel); box-shadow: inset 0 0 0 1px var(--dbt-charge-line);
    animation: dbt-charge-in 520ms var(--dbt-charge-ease) both; animation-delay: calc(var(--i, 0) * 50ms);
    & dt { font: 600 10px var(--dbt-charge-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbt-charge-muted); }
    & dd { display: flex; align-items: baseline; gap: 4px; margin-top: 2px; }
    & b { font-size: clamp(19px, 2.15cqi, 25px); font-weight: 650; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; line-height: 1.1; }
    & small { font-size: 12px; color: var(--dbt-charge-muted); }
  }
  .dbt-charge-kpi-main { background: linear-gradient(135deg, color-mix(in oklch, var(--dbt-charge-volt) 13%, var(--dbt-charge-panel)), var(--dbt-charge-panel) 70%); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbt-charge-volt) 40%, transparent); & b { color: var(--dbt-charge-volt); } }
  .dbt-charge-kfoot { display: block; margin-top: 3px; font: 10.5px var(--dbt-charge-mono); color: var(--dbt-charge-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }

  /* ---------- main + views ---------- */
  .dbt-charge-main { grid-area: main; min-height: 0; min-width: 0; display: grid; padding: 0 18px 16px; }
  .dbt-charge-view { min-height: 0; min-width: 0; display: grid; gap: 12px; transition: opacity 320ms var(--dbt-charge-ease), translate 420ms var(--dbt-charge-ease); @starting-style { opacity: 0; translate: 0 8px; } }
  .dbt-charge-panel { position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dbt-charge-panel); box-shadow: inset 0 0 0 1px var(--dbt-charge-line); }
  .dbt-charge-ph { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 12px; padding: 12px 14px 8px; & h3 { font-size: 13px; font-weight: 650; } }
  .dbt-charge-hint { font: 11px var(--dbt-charge-mono); color: var(--dbt-charge-faint); font-weight: 400; margin-left: 4px; }
  .dbt-charge-seg {
    display: inline-flex; flex-wrap: wrap; gap: 2px; padding: 2px; border-radius: 8px; background: var(--dbt-charge-deep); box-shadow: inset 0 0 0 1px var(--dbt-charge-line);
    & button { padding: 4px 10px; border-radius: 6px; font-size: 12px; font-weight: 560; color: var(--dbt-charge-muted); transition: color 160ms, background-color 160ms; }
    & button:hover { color: var(--dbt-charge-ink); }
    & button[aria-checked="true"] { background: var(--dbt-charge-raise); color: var(--dbt-charge-ink); box-shadow: inset 0 0 0 1px var(--dbt-charge-line-2); }
  }
  .dbt-charge-tip {
    position: absolute; z-index: 5; left: 0; top: 0; pointer-events: none; min-width: 120px; padding: 7px 9px; border-radius: 8px;
    background: color-mix(in oklch, var(--dbt-charge-bg), white 13%); box-shadow: 0 0 0 1px var(--dbt-charge-line-2), 0 10px 26px -8px black;
    font: 11px/1.45 var(--dbt-charge-mono); font-variant-numeric: tabular-nums; white-space: nowrap;
    opacity: 0; scale: 0.96; transition: opacity 140ms, scale 160ms var(--dbt-charge-ease);
    &[data-on] { opacity: 1; scale: 1; }
    & b { display: block; font: 600 11.5px system-ui, sans-serif; margin-bottom: 2px; }
    & span { display: flex; justify-content: space-between; gap: 14px; color: var(--dbt-charge-muted); }
    & em { font-style: normal; color: var(--dbt-charge-ink); }
  }

  /* ---------- live ---------- */
  .dbt-charge-livev { grid-template-columns: 228px minmax(0, 1fr); }
  .dbt-charge-sites { min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 6px; padding: 1px; scrollbar-width: thin; scrollbar-color: var(--dbt-charge-line-2) transparent; }
  .dbt-charge-srow {
    position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 3px 10px; padding: 11px 12px 12px; border-radius: 11px; text-align: left;
    background: var(--dbt-charge-panel); box-shadow: inset 0 0 0 1px var(--dbt-charge-line); transition: background-color 160ms, box-shadow 200ms;
    animation: dbt-charge-in 520ms var(--dbt-charge-ease) both; animation-delay: calc(var(--i) * 60ms + 120ms);
    &:hover { background: var(--dbt-charge-raise); }
    &[aria-selected="true"] { background: var(--dbt-charge-raise); box-shadow: inset 0 0 0 1.5px var(--dbt-charge-volt); }
    & .dbt-charge-sn { font-weight: 640; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & .dbt-charge-skw { font: 600 13px var(--dbt-charge-mono); font-variant-numeric: tabular-nums; text-align: right; }
    & .dbt-charge-skw small { font-weight: 400; font-size: 10px; color: var(--dbt-charge-muted); margin-left: 2px; }
