.dbt-water {
  /* re-theme: background, ink, accent (selection only). Colour is reserved for alarms, by priority. */
  --dbt-water-bg: oklch(0.885 0.004 95);
  --dbt-water-ink: oklch(0.26 0.008 250);
  --dbt-water-accent: oklch(0.47 0.085 242);
  --dbt-water-p1: oklch(0.56 0.21 27);
  --dbt-water-p2: oklch(0.71 0.17 52);
  --dbt-water-p3: oklch(0.86 0.16 98);
  --dbt-water-p4: oklch(0.6 0.17 322);
