  --dbt-water-well: color-mix(in oklch, var(--dbt-water-bg), white 22%);
  --dbt-water-rail-bg: color-mix(in oklch, var(--dbt-water-bg), var(--dbt-water-ink) 7%);
  --dbt-water-line: color-mix(in oklch, var(--dbt-water-ink) 13%, transparent);
  --dbt-water-line-2: color-mix(in oklch, var(--dbt-water-ink) 24%, transparent);
  --dbt-water-muted: color-mix(in oklch, var(--dbt-water-ink) 64%, var(--dbt-water-bg));
  --dbt-water-faint: color-mix(in oklch, var(--dbt-water-ink) 44%, var(--dbt-water-bg));
  --dbt-water-pipe: color-mix(in oklch, var(--dbt-water-ink) 52%, var(--dbt-water-bg));
  --dbt-water-hover: color-mix(in oklch, var(--dbt-water-ink) 6%, transparent);
  --dbt-water-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dbt-water-spring: linear(0, 0.013, 0.05 2.4%, 0.2 5.3%, 0.81 14%, 0.99 18%, 1.07 21.6%, 1.08 25%, 1.05 30%, 1.007 37.5%, 0.994 45%, 1);
  --dbt-water-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbt-water-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 12px;
  background: var(--dbt-water-bg);
  color: var(--dbt-water-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light;
  accent-color: var(--dbt-water-accent);
  box-shadow: inset 0 0 0 1px var(--dbt-water-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbt-water-accent); outline-offset: 2px; border-radius: 4px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & dl, & dd { margin: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbt-water-eyebrow { font: 600 10px/1.3 var(--dbt-water-mono); letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbt-water-muted); }
  .dbt-water-app { display: grid; height: 100%; grid-template-columns: 60px minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "rail head" "rail banner" "rail main"; }

  /* ---------- rail ---------- */
  .dbt-water-rail { grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 18px; padding: 14px 0; background: var(--dbt-water-rail-bg); border-right: 1px solid var(--dbt-water-line); }
