    &:hover { color: var(--dbt-water-ink); background: var(--dbt-water-hover); }
    &[aria-selected="true"] { color: var(--dbt-water-ink); background: var(--dbt-water-panel); box-shadow: inset 0 0 0 1px var(--dbt-water-line-2); }
    &[aria-selected="true"]::before { content: ""; position: absolute; left: -9px; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dbt-water-accent); }
  }
