  .dbt-water-h { font-size: clamp(19px, 2.2cqi, 25px); font-weight: 720; letter-spacing: -0.02em; line-height: 1.05; }
  .dbt-water-counts { display: flex; gap: 6px; }
  .dbt-water-count {
    display: flex; align-items: center; gap: 7px; padding: 4px 10px 4px 6px; border-radius: 8px; background: var(--dbt-water-panel); box-shadow: inset 0 0 0 1px var(--dbt-water-line);
    font: 600 12px var(--dbt-water-mono); font-variant-numeric: tabular-nums; transition: opacity 200ms;
