  .dbt-water-gt { font: 800 9.5px var(--dbt-water-mono); fill: var(--dbt-water-ink); text-anchor: middle; }
  [data-p="1"] { --pc: var(--dbt-water-p1); } [data-p="2"] { --pc: var(--dbt-water-p2); } [data-p="3"] { --pc: var(--dbt-water-p3); } [data-p="4"] { --pc: var(--dbt-water-p4); }
  [data-p="1"] .dbt-water-gt, [data-p="4"] .dbt-water-gt { fill: white; }
