  /* ---------- main ---------- */
  .dbt-water-main { grid-area: main; min-height: 0; min-width: 0; display: grid; padding: 0 18px 16px; }
  .dbt-water-view { min-height: 0; min-width: 0; display: grid; gap: 10px; transition: opacity 300ms var(--dbt-water-ease), translate 400ms var(--dbt-water-ease); @starting-style { opacity: 0; translate: 0 8px; } }
  .dbt-water-panel { position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 10px; background: var(--dbt-water-panel); box-shadow: inset 0 0 0 1px var(--dbt-water-line); animation: dbt-water-in 480ms var(--dbt-water-ease) both; animation-delay: calc(var(--i, 0) * 70ms); }
  .dbt-water-ph { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 12px; padding: 10px 12px 6px; & h3 { font-size: 13px; font-weight: 680; } }
  .dbt-water-hint { font: 10.5px var(--dbt-water-mono); color: var(--dbt-water-faint); font-weight: 400; }
  .dbt-water-tt { min-width: 0; & h3 { font-family: var(--dbt-water-mono); } & p { font-size: 11.5px; color: var(--dbt-water-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } }
  .dbt-water-seg {
    display: inline-flex; gap: 2px; padding: 2px; border-radius: 7px; background: var(--dbt-water-well); box-shadow: inset 0 0 0 1px var(--dbt-water-line);
    & button { padding: 3px 9px; border-radius: 5px; font-size: 11.5px; font-weight: 580; color: var(--dbt-water-muted); font-variant-numeric: tabular-nums; }
    & button:hover { color: var(--dbt-water-ink); }
    & button[aria-checked="true"] { background: var(--dbt-water-panel); color: var(--dbt-water-ink); box-shadow: 0 0 0 1px var(--dbt-water-line-2), 0 1px 2px var(--dbt-water-line); }
  }
  .dbt-water-tip {
    position: absolute; z-index: 5; left: 0; top: 0; pointer-events: none; min-width: 130px; padding: 7px 9px; border-radius: 7px;
    background: var(--dbt-water-ink); color: var(--dbt-water-bg); box-shadow: 0 8px 22px -8px color-mix(in oklch, var(--dbt-water-ink) 60%, transparent);
    font: 11px/1.45 var(--dbt-water-mono); font-variant-numeric: tabular-nums; white-space: nowrap;
    opacity: 0; scale: 0.96; transition: opacity 140ms, scale 160ms var(--dbt-water-ease);
    &[data-on] { opacity: 1; scale: 1; }
    & b { display: block; font: 600 11.5px system-ui, sans-serif; margin-bottom: 2px; }
    & span { display: flex; justify-content: space-between; gap: 14px; color: color-mix(in oklch, var(--dbt-water-bg) 70%, var(--dbt-water-ink)); }
    & em { font-style: normal; color: var(--dbt-water-bg); }
  }

  /* ---------- network view ---------- */
  .dbt-water-netv { grid-template-columns: minmax(0, 1.62fr) minmax(0, 1fr); grid-template-rows: minmax(0, 1.08fr) minmax(0, 1fr); grid-template-areas: "schem alarms" "schem trend"; }
  .dbt-water-schem { grid-area: schem; }
  .dbt-water-alarms { grid-area: alarms; --i: 1; }
  .dbt-water-trend { grid-area: trend; --i: 2; }
  .dbt-water-key {
    display: flex; gap: 12px; font-size: 11px; color: var(--dbt-water-muted);
    & li { display: flex; align-items: center; gap: 5px; }
    & i { display: block; }
  }
  .dbt-water-k-band { width: 18px; height: 7px; border-radius: 2px; background: white; box-shadow: inset 0 0 0 1px var(--dbt-water-line-2); }
  .dbt-water-k-ptr { width: 0; height: 0; border: 5px solid transparent; border-top: 7px solid var(--dbt-water-ink); border-bottom: 0; }
  .dbt-water-k-lim { width: 2px; height: 10px; background: var(--dbt-water-ink); }
  .dbt-water-svgwrap { position: relative; flex: 1; min-height: 0; padding: 0 8px 8px; }
  .dbt-water-limt { fill-opacity: 1; }
  .dbt-water-map { width: 100%; height: 100%; overflow: visible; }
  :where(.dbt-water-map text) { font-family: system-ui, sans-serif; fill: var(--dbt-water-ink); }
  .dbt-water-pipe { fill: none; stroke: var(--dbt-water-pipe); stroke-width: 6; stroke-linecap: round; stroke-linejoin: round; }
  .dbt-water-flow { fill: none; stroke: color-mix(in oklch, var(--dbt-water-bg), white 75%); stroke-width: 2; stroke-dasharray: 1.5 11; stroke-linecap: round; }
  .dbt-water-pipes { animation: dbt-water-pipe 1100ms var(--dbt-water-ease) both 150ms; }
  .dbt-water-box { fill: var(--dbt-water-panel); stroke: var(--dbt-water-line-2); stroke-width: 1; }
  .dbt-water-box-dk { fill: var(--dbt-water-well); stroke: var(--dbt-water-line-2); }
  .dbt-water-nl { font: 650 9.5px var(--dbt-water-mono); letter-spacing: 0.08em; text-transform: uppercase; fill: var(--dbt-water-muted); }
  .dbt-water-nn { font: 680 12px system-ui, sans-serif; }
  .dbt-water-sub { font: 10px var(--dbt-water-mono); fill: var(--dbt-water-faint); }
  .dbt-water-sym { fill: var(--dbt-water-panel); stroke: var(--dbt-water-ink); stroke-width: 1.3; stroke-linejoin: round; }
  .dbt-water-sym-on { fill: var(--dbt-water-ink); }
  .dbt-water-sym-trip { fill: var(--dbt-water-p2); }
  .dbt-water-tank-fill { fill: color-mix(in oklch, var(--dbt-water-ink) 22%, var(--dbt-water-panel)); transform-box: fill-box; transform-origin: 50% 100%; scale: 1 var(--dbt-water-lvl); transition: --dbt-water-lvl 1.2s var(--dbt-water-ease); }
  .dbt-water-meas {
    cursor: pointer; outline: none;
    & .dbt-water-hl { fill: transparent; stroke: transparent; stroke-width: 1.5; transition: fill 140ms, stroke 140ms; }
    &:hover .dbt-water-hl { fill: var(--dbt-water-hover); }
    &:focus-visible .dbt-water-hl { stroke: var(--dbt-water-accent); stroke-width: 2; }
    &[data-sel] .dbt-water-hl { fill: color-mix(in oklch, var(--dbt-water-accent) 12%, transparent); stroke: var(--dbt-water-accent); }
    & .dbt-water-mv { font: 650 12.5px var(--dbt-water-mono); font-variant-numeric: tabular-nums; }
    & .dbt-water-mu { font: 10px var(--dbt-water-mono); fill: var(--dbt-water-muted); }
    & .dbt-water-mt { font: 600 9.5px var(--dbt-water-mono); fill: var(--dbt-water-muted); letter-spacing: 0.04em; }
  }
  .dbt-water-ai-track { fill: color-mix(in oklch, var(--dbt-water-ink) 13%, var(--dbt-water-panel)); }
  .dbt-water-ai-band { fill: white; }
  .dbt-water-ai-lim { stroke: var(--dbt-water-ink); stroke-width: 1.4; }
  .dbt-water-ai-ptr { fill: var(--dbt-water-ink); transition: translate 700ms var(--dbt-water-spring); }
  .dbt-water-meas[data-p] {
    & .dbt-water-ai-ptr { fill: var(--pc); stroke: var(--dbt-water-ink); stroke-width: 0.8; }
    & .dbt-water-mv { fill: color-mix(in oklch, var(--pc) 70%, var(--dbt-water-ink)); }
    & .dbt-water-ai-track { fill: color-mix(in oklch, var(--pc) 35%, var(--dbt-water-panel)); }
  }
  .dbt-water-meas[data-p="3"] .dbt-water-mv { fill: var(--dbt-water-ink); }
  .dbt-water-meas[data-stale] { & .dbt-water-mv { fill: var(--dbt-water-faint); font-style: italic; } & .dbt-water-ai-ptr { fill: var(--dbt-water-faint); } }
  .dbt-water-mg { opacity: 0; transition: opacity 200ms; }
  .dbt-water-meas[data-p] .dbt-water-mg { opacity: 1; }
  .dbt-water-meas[data-unack] .dbt-water-mg { animation: dbt-water-blink 1.1s steps(2, jump-none) infinite; }
  .dbt-water-zone { font: 10.5px var(--dbt-water-mono); fill: var(--dbt-water-muted); font-variant-numeric: tabular-nums; }
  .dbt-water-zone-b { font: 650 11px var(--dbt-water-mono); fill: var(--dbt-water-ink); font-variant-numeric: tabular-nums; }

  /* alarms */
  .dbt-water-pchips {
    display: flex; gap: 4px;
    & button { display: flex; align-items: center; gap: 4px; padding: 2px 7px 2px 3px; border-radius: 99px; font: 600 10.5px var(--dbt-water-mono); color: var(--dbt-water-muted); box-shadow: inset 0 0 0 1px var(--dbt-water-line-2); transition: opacity 160ms, background-color 160ms; }
    & button[aria-pressed="false"] { opacity: 0.45; }
    & button[aria-pressed="false"] .dbt-water-glyph { filter: grayscale(1); }
    & button:hover { background: var(--dbt-water-hover); }
    & .dbt-water-glyph { width: 14px; height: 14px; }
  }
  .dbt-water-alist { flex: 1; min-height: 0; overflow: auto; padding: 0 8px 8px; scrollbar-width: thin; scrollbar-color: var(--dbt-water-line-2) transparent; }
  .dbt-water-agrp { position: sticky; top: 0; z-index: 1; padding: 6px 4px 4px; background: var(--dbt-water-panel); font: 600 9.5px var(--dbt-water-mono); letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbt-water-faint); }
  .dbt-water-alarm {
    position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; grid-template-areas: "g t time" "g m btn"; gap: 1px 9px; align-items: center;
    padding: 7px 8px 7px 9px; margin-bottom: 4px; border-radius: 8px; cursor: pointer; text-align: left; width: 100%;
    background: var(--dbt-water-panel); box-shadow: inset 0 0 0 1px var(--dbt-water-line);
    transition: background-color 160ms, box-shadow 160ms;
    & .dbt-water-glyph { grid-area: g; align-self: start; margin-top: 1px; }
    & .dbt-water-at { grid-area: t; font-size: 12.5px; font-weight: 640; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & .dbt-water-at b { font-family: var(--dbt-water-mono); font-weight: 680; margin-right: 5px; }
    & .dbt-water-am { grid-area: m; font: 11px var(--dbt-water-mono); color: var(--dbt-water-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
    & .dbt-water-atime { grid-area: time; font: 10.5px var(--dbt-water-mono); color: var(--dbt-water-faint); text-align: right; }
    & .dbt-water-ack { grid-area: btn; justify-self: end; padding: 1px 8px; border-radius: 6px; font-size: 11px; font-weight: 620; background: var(--dbt-water-panel); box-shadow: inset 0 0 0 1px var(--dbt-water-line-2); }
    & .dbt-water-ack:hover { background: white; }
    & .dbt-water-st { grid-area: btn; justify-self: end; font: 600 9.5px var(--dbt-water-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--dbt-water-faint); }
    &:hover { background: color-mix(in oklch, var(--dbt-water-panel), var(--dbt-water-ink) 4%); }
    &[data-unack] { background: color-mix(in oklch, var(--pc) 13%, var(--dbt-water-panel)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--pc) 50%, transparent), inset 3px 0 0 var(--pc); }
    &[data-unack] .dbt-water-glyph { animation: dbt-water-blink 1.1s steps(2, jump-none) infinite; }
    &[aria-current="true"] { box-shadow: inset 0 0 0 2px var(--dbt-water-accent); }
    &[data-leaving] { animation: dbt-water-out 380ms var(--dbt-water-ease) forwards; pointer-events: none; }
  }
  .dbt-water-asel { position: absolute; inset: 0; z-index: 0; border-radius: inherit; }
  .dbt-water-alarm > :not(.dbt-water-asel) { position: relative; z-index: 1; pointer-events: none; }
  .dbt-water-alarm > .dbt-water-ack { pointer-events: auto; }
  .dbt-water-aempty { padding: 24px 8px; text-align: center; font-size: 12px; color: var(--dbt-water-faint); }

  /* trend */
  .dbt-water-tplot, .dbt-water-nplot, .dbt-water-rplot { position: relative; flex: 1; min-height: 110px; margin: 0 6px 6px; border-radius: 6px; }
  .dbt-water-tsvg, .dbt-water-nsvg, .dbt-water-rsvg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dbt-water-ax line { stroke: var(--dbt-water-line); }
  .dbt-water-ax text { font: 9.5px var(--dbt-water-mono); fill: var(--dbt-water-faint); font-variant-numeric: tabular-nums; }
  .dbt-water-band { fill: white; opacity: 0.85; }
  .dbt-water-lim { stroke-width: 1.2; stroke-dasharray: 4 3; }
  .dbt-water-limt { font: 600 9px var(--dbt-water-mono); paint-order: stroke; stroke: var(--dbt-water-panel); stroke-width: 3px; }
  .dbt-water-tl { fill: none; stroke: var(--dbt-water-ink); stroke-width: 1.6; stroke-linejoin: round; stroke-dasharray: 1; animation: dbt-water-draw 1000ms var(--dbt-water-ease) both; }
  .dbt-water-evt { stroke-width: 1; stroke-dasharray: 2 2; }
  .dbt-water-xh { stroke: var(--dbt-water-ink); stroke-opacity: 0.55; stroke-dasharray: 3 3; }
  .dbt-water-dot { fill: var(--dbt-water-ink); stroke: var(--dbt-water-panel); stroke-width: 2; }
  .dbt-water-tplot:not([data-hov]), .dbt-water-nplot:not([data-hov]) { & .dbt-water-xh, & .dbt-water-dot { visibility: hidden; } }
  .dbt-water-now { font: 600 9px var(--dbt-water-mono); fill: var(--dbt-water-accent); }

  /* ---------- night flow ---------- */
  .dbt-water-nightv { grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nk nk" "tab chart"; }
  .dbt-water-nk { grid-area: nk; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
  .dbt-water-nkpi {
    padding: 8px 12px 9px; border-radius: 10px; background: var(--dbt-water-panel); box-shadow: inset 0 0 0 1px var(--dbt-water-line); min-width: 0;
    animation: dbt-water-in 460ms var(--dbt-water-ease) both; animation-delay: calc(var(--i) * 55ms);
    & dt { font: 600 10px var(--dbt-water-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbt-water-muted); }
    & dd b { font-size: clamp(18px, 2cqi, 23px); font-weight: 680; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
    & dd small { margin-left: 3px; font-size: 11.5px; color: var(--dbt-water-muted); }
    & dd p { font: 10.5px var(--dbt-water-mono); color: var(--dbt-water-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  }
  .dbt-water-ntab { grid-area: tab; --i: 1; }
  .dbt-water-nchart { grid-area: chart; --i: 2; }
  .dbt-water-scroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbt-water-line-2) transparent; border-top: 1px solid var(--dbt-water-line); }
  .dbt-water-table {
    width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12px; font-variant-numeric: tabular-nums;
    & th { position: sticky; top: 0; z-index: 2; padding: 0; background: var(--dbt-water-panel); box-shadow: inset 0 -1px 0 var(--dbt-water-line); text-align: left; font-weight: 400; }
    & th button { display: flex; align-items: center; gap: 4px; width: 100%; padding: 7px 9px; font: 600 9.5px var(--dbt-water-mono); letter-spacing: 0.07em; text-transform: uppercase; color: var(--dbt-water-muted); white-space: nowrap; }
    & th button::after { content: ""; width: 0; height: 0; border: 4px solid transparent; opacity: 0; }
    & th[aria-sort="ascending"] button::after { opacity: 1; border-bottom-color: currentColor; translate: 0 -2px; }
    & th[aria-sort="descending"] button::after { opacity: 1; border-top-color: currentColor; translate: 0 2px; }
    & th[aria-sort="ascending"] button, & th[aria-sort="descending"] button { color: var(--dbt-water-ink); }
    & .dbt-water-num, & .dbt-water-num button { text-align: right; justify-content: flex-end; }
    & td { padding: 7px 9px; border-bottom: 1px solid var(--dbt-water-line); white-space: nowrap; }
    & tbody tr { transition: background-color 140ms; }
    & tbody tr[tabindex] { cursor: pointer; }
    & tbody tr:hover { background: var(--dbt-water-hover); }
    & tbody tr[aria-selected="true"] { background: color-mix(in oklch, var(--dbt-water-accent) 11%, transparent); box-shadow: inset 3px 0 0 var(--dbt-water-accent); }
    & tbody tr:focus-visible { outline: 2px solid var(--dbt-water-accent); outline-offset: -2px; }
    & tfoot td { position: sticky; bottom: 0; background: var(--dbt-water-well); font-weight: 650; border-bottom: 0; box-shadow: inset 0 1px 0 var(--dbt-water-line-2); }
  }
  .dbt-water-dma { display: grid; line-height: 1.25; & b { font-weight: 650; } & small { font: 10px var(--dbt-water-mono); color: var(--dbt-water-faint); } }
  .dbt-water-lph { display: inline-flex; align-items: center; gap: 6px; justify-content: flex-end; & i { width: 40px; height: 5px; border-radius: 3px; background: linear-gradient(90deg, var(--c, var(--dbt-water-ink)) var(--w), var(--dbt-water-line) var(--w)); } }
  .dbt-water-chg { font-family: var(--dbt-water-mono); font-size: 11px; }
  .dbt-water-chg[data-up] { color: color-mix(in oklch, var(--dbt-water-p1) 80%, var(--dbt-water-ink)); font-weight: 650; }
  .dbt-water-bar-l { fill: color-mix(in oklch, var(--dbt-water-ink) 20%, var(--dbt-water-panel)); }
  .dbt-water-bar-k { fill: color-mix(in oklch, var(--dbt-water-ink) 62%, var(--dbt-water-panel)); }
  .dbt-water-nb { transform-box: fill-box; transform-origin: 50% 100%; animation: dbt-water-grow 560ms var(--dbt-water-ease) both; animation-delay: calc(var(--i) * 12ms); transition: opacity 140ms; }
  .dbt-water-nb[data-burst] .dbt-water-bar-k { fill: var(--dbt-water-p2); }
  .dbt-water-nplot[data-hov] .dbt-water-nb:not([data-on]) { opacity: 0.45; }
  .dbt-water-tgt { stroke: var(--dbt-water-accent); stroke-width: 1.4; stroke-dasharray: 5 3; }
  .dbt-water-lg {
    display: flex; flex-wrap: wrap; gap: 4px 14px; padding: 0 12px 10px; font-size: 11.5px; color: var(--dbt-water-muted);
    & li { display: flex; align-items: center; gap: 6px; }
    & i { width: 12px; height: 9px; border-radius: 2px; }
    & [data-c="legit"] i { background: color-mix(in oklch, var(--dbt-water-ink) 20%, var(--dbt-water-panel)); }
    & [data-c="leak"] i { background: color-mix(in oklch, var(--dbt-water-ink) 62%, var(--dbt-water-panel)); }
    & [data-c="tgt"] i { height: 0; border-top: 2px dashed var(--dbt-water-accent); border-radius: 0; }
  }

  /* ---------- alarm log ---------- */
  .dbt-water-logv { grid-template-rows: minmax(150px, 0.62fr) minmax(0, 1fr); }
  .dbt-water-logp { --i: 1; }
  .dbt-water-rb { transform-box: fill-box; transform-origin: 50% 100%; animation: dbt-water-grow 520ms var(--dbt-water-ease) both; animation-delay: calc(var(--i) * 18ms); }
  .dbt-water-rb rect { fill: color-mix(in oklch, var(--dbt-water-ink) 45%, var(--dbt-water-panel)); }
  .dbt-water-rb[data-lvl="warn"] rect { fill: var(--dbt-water-p3); stroke: var(--dbt-water-ink); stroke-width: 0.8; }
  .dbt-water-rb[data-lvl="flood"] rect { fill: var(--dbt-water-p2); stroke: var(--dbt-water-ink); stroke-width: 0.8; }
  .dbt-water-rplot:has(.dbt-water-rb:hover) .dbt-water-rb:not(:hover) { opacity: 0.5; }
  .dbt-water-ref { stroke: var(--dbt-water-ink); stroke-width: 1; stroke-dasharray: 4 3; opacity: 0.6; }
  .dbt-water-ltable td { padding-block: 6px; }
  .dbt-water-ltable .dbt-water-wide { width: 99%; }
  .dbt-water-ltable td.dbt-water-wide { max-width: 0; overflow: hidden; text-overflow: ellipsis; }
  .dbt-water-pcell { display: inline-flex; align-items: center; gap: 5px; font: 600 11px var(--dbt-water-mono); & .dbt-water-glyph { width: 15px; height: 15px; } }
  .dbt-water-state { font: 600 9.5px var(--dbt-water-mono); letter-spacing: 0.06em; text-transform: uppercase; padding: 1px 6px; border-radius: 4px; color: var(--dbt-water-muted); box-shadow: inset 0 0 0 1px var(--dbt-water-line-2); }
  .dbt-water-state[data-s="unack"] { color: var(--dbt-water-ink); background: color-mix(in oklch, var(--pc) 30%, var(--dbt-water-panel)); box-shadow: inset 0 0 0 1px var(--pc); }
  .dbt-water-state[data-s="ack"] { color: var(--dbt-water-ink); box-shadow: inset 0 0 0 1px var(--pc); }
  .dbt-water-state[data-s="rtn"] { color: var(--dbt-water-ink); background: color-mix(in oklch, var(--pc) 14%, var(--dbt-water-panel)); box-shadow: inset 0 0 0 1px var(--pc); border: 1px dashed var(--pc); }
  .dbt-water-mono { font-family: var(--dbt-water-mono); font-size: 11.5px; }

  /* ---------- container responsiveness ---------- */
  @container (max-width: 1060px) {
    .dbt-water-netv { grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); }
    .dbt-water-key { display: none; }
  }
  @container (max-width: 960px) {
    .dbt-water-main { display: block; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbt-water-line-2) transparent; }
    .dbt-water-view { min-height: auto; }
    .dbt-water-netv { grid-template-columns: repeat(2, minmax(0, 1fr)); grid-template-rows: auto 300px; grid-template-areas: "schem schem" "alarms trend"; }
    .dbt-water-svgwrap { flex: none; aspect-ratio: 640 / 456; }
    .dbt-water-count small { display: none; }
    .dbt-water-nightv { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto 300px; grid-template-areas: "nk" "tab" "chart"; }
    .dbt-water-ntab .dbt-water-scroll { flex: none; }
    .dbt-water-nk { grid-template-columns: repeat(2, minmax(0, 1fr)); }
