const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const fmt = (v, d = 0) => v.toLocaleString('en-GB', { minimumFractionDigits: d, maximumFractionDigits: d });
const sgn = (v, d = 1) => (v >= 0 ? '+' : '−') + fmt(Math.abs(v), d);
const pad = (n) => String(n).padStart(2, '0');
const hash = (a, b, c) => { let x = (a * 374761393 + b * 668265263 + c * 1103515245) | 0; x = Math.imul(x ^ (x >>> 13), 1274126177); x ^= x >>> 16; return (x >>> 0) / 4294967296; };
const sm = (h, a, b) => { const x = clamp((h - a) / (b - a), 0, 1); return x * x * (3 - 2 * x); };
const g = (h, mu, s) => { let d = Math.abs(h - mu); d = Math.min(d, 24 - d); return Math.exp(-(d * d) / (2 * s * s)); };
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

/* ---------- hydraulic model ---------- */
// Time is seconds from midnight on Fri 2 Oct 2026 (negative = earlier days). Every number on screen, the trend,
// the night-flow table and the alarm messages, is read from these same functions, so they agree with each other.
const T0 = Date.UTC(2026, 9, 2);
const NOW0 = 4 * 3600 + 12 * 60, S5 = 300, NS = 72 * 12 + 1, LAST = Math.floor(NOW0 / S5) * S5;
const tAt = (i) => LAST - (NS - 1 - i) * S5;
const todH = (s) => (((s / 3600) % 24) + 24) % 24;
const dayOf = (s) => Math.floor(s / 86400);
const hhmm = (s) => { const m = Math.floor((((s % 86400) + 86400) % 86400) / 60); return pad(Math.floor(m / 60)) + ':' + pad(m % 60); };
const dayLab = (s) => { const d = new Date(T0 + dayOf(s) * 864e5); return WD[d.getUTCDay()] + ' ' + d.getUTCDate(); };
const BURST = 2 * 3600 + 5 * 60, TRIP = 3 * 3600 + 22 * 60, COMMS = 3 * 3600 + 31 * 60, AREA = 1200, SRMAX = 5.5;
const ramp = (s, a, w) => clamp((s - a) / w, 0, 1);
const bump = (s, c, w) => Math.exp(-(((s - c) / w) ** 2));
const shape = (h) => 1.6 * g(h, 7.6, 1.3) + 1.0 * g(h, 12.8, 2.4) + 1.3 * g(h, 19.2, 1.9);
const DMAS = [
  { id: '04', name: 'Old Town', props: 3420, nhh: 1.1, day: 14.6, dz: 0.62, k: 0.0012, tgt: 4.5 },
  { id: '07', name: 'Millfield', props: 4870, nhh: 0.6, day: 19.8, dz: 0.4, k: 0.0008, tgt: 6.0 },
  { id: '09', name: 'Ashgrove', props: 2150, nhh: 0.25, day: 8.4, dz: 0.35, k: 0.002, tgt: 2.5 },
  { id: '11', name: 'Quayside', props: 2960, nhh: 2.4, day: 18.0, dz: 0.93, k: 0.0006, tgt: 3.4 },
  { id: '12', name: 'Harrow Heights', props: 1780, nhh: 0.15, day: 7.1, dz: 3.1, k: 0.0047, tgt: 2.5 }
];
DMAS.forEach((D) => { D.legit = (D.props * 1.7) / 3600 + D.nhh; D.n = +D.id; });
function leak(D, s) {
  const n = -dayOf(s), r = hash(n + 7, D.n, 3) - 0.5;
  if (D.id === '04') return 6.18 + 0.3 * Math.sin(n * 0.9) + 0.5 * r;
  if (D.id === '07') return Math.max(6.4, 10.7 - 0.095 * n) + 0.45 * r;
  if (D.id === '09') return 2.13 + 0.3 * r;
  if (D.id === '11') return 3.82 + 0.5 * r + 14.1 * ramp(s, BURST, 600);
  return (n < 19 ? 2.11 : 4.95) + 0.3 * r;
}
const nz = (s, a, amp) => (hash(Math.floor(s / S5), a, 11) - 0.5) * amp;
const FM = (D, s) => { const v = D.legit + (D.day - D.legit) * shape(todH(s)) + leak(D, s); return v * (1 + nz(s, D.n, 0.024)); };
const setP = (h) => 3.05 + 0.4 * sm(h, 5, 6) * (1 - sm(h, 22.5, 23.5));
function PRV(D, s) {
  if (D.id === '12') return 5.4 + nz(s, 40, 0.06);
  let v = setP(todH(s)) + nz(s, 20 + D.n, 0.03);
  if (D.id === '04') v += 0.84 * bump(s, 3 * 3600 + 49 * 60, 420);
  if (D.id === '11') v -= 0.78 * ramp(s, BURST, 600);
  return v;
}
const CP = (D, s) => PRV(D, s) - D.dz - D.k * FM(D, s) ** 2 - (D.id === '11' ? 0.2 * ramp(s, BURST, 600) : 0) + nz(s, 30 + D.n, 0.02);
const pumped = (s) => { const h = todH(s); let q = h >= 23 || h < 6.5 ? 92 : 70.5; if (s >= TRIP && s < TRIP + 180) q = 0; return q * (1 + nz(s, 50, 0.01)); };
const PS1P = (s) => 6.95 + 0.25 * (pumped(s) / 92) - (pumped(s) < 10 ? 1.3 : 0) + nz(s, 51, 0.04);
const OUT = (s) => DMAS.reduce((a, D) => a + FM(D, s), 0);

/* ---------- tags ---------- */
const TAGS = {};
const mk = (id, o) => { TAGS[id] = Object.assign({ id, lim: [null, null], lp: [null, null], dec: 2 }, o); };
const DOMS = (s) => DMAS.find((D) => D.id === s);
mk('WTW-FT', { desc: 'Hollin Moor WTW · treated water out', unit: 'l/s', dec: 1, sc: [0, 120], band: [55, 100], f: pumped });
mk('PS1-PT', { desc: 'PS1 Ridgeway · discharge pressure', unit: 'bar', sc: [4, 9], band: [6.2, 7.6], lim: [5.8, 7.9], lp: [2, 3], f: PS1P });
mk('SR-LT', { desc: 'Cragg Hill SR · water level', unit: 'm', sc: [0, SRMAX], band: [2.6, 5.2], lim: [2.2, 5.35], lp: [2, 3] });
DMAS.forEach((D) => {
  const mnf7 = Array.from({ length: 7 }, (_, k) => D.legit + leak(D, -(k + 1) * 86400 + 3.5 * 3600)).reduce((a, b) => a + b, 0) / 7;
