  if (D.id === '12') mk('BS12-PT', { desc: 'BS-12 booster · discharge pressure', unit: 'bar', sc: [3, 8], band: [4.9, 5.9], lim: [4.5, 6.2], lp: [3, 3], f: (s) => PRV(D, s) });
  else mk('PRV' + D.id + '-PT', { desc: `PRV-${D.id} · outlet pressure into DMA ${D.id}`, unit: 'bar', sc: [1, 5], band: [2.9, 3.6], lim: [2.5, 3.8], lp: [3, 3], f: (s) => PRV(D, s) });
  mk('FM-' + D.id, { desc: `DMA ${D.id} ${D.name} · inlet flow`, unit: 'l/s', dec: 1, sc: [0, 45], band: [mnf7 * 0.85, D.legit + (D.day - D.legit) * 1.62 + mnf7 - D.legit], lim: [null, D.nightLim], lp: [null, 2], limWin: [0, 5], f: (s) => FM(D, s) });
  mk('CP-' + D.id, { desc: `DMA ${D.id} ${D.name} · critical point pressure`, unit: 'bar', sc: [0, 4], band: [1.8, 3.4], lim: [1.5, null], lp: [1, null], f: (s) => CP(D, s), stale: D.id === '07' ? COMMS : 0 });
});
Object.values(TAGS).forEach((T) => { if (T.f) T.ser = Array.from({ length: NS }, (_, i) => (T.stale && tAt(i) > T.stale ? null : T.f(tAt(i)))); });
// reservoir level is integrated from inflow minus the five DMA inflows, then anchored to the gauge reading
(() => {
  const T = TAGS['SR-LT'], ser = [0];
  for (let i = 1; i < NS; i++) ser.push(ser[i - 1] + ((pumped(tAt(i)) - OUT(tAt(i))) * S5) / 1000 / AREA);
  const off = 4.31 - ser[NS - 1];
  T.ser = ser.map((v) => v + off);
})();

/* ---------- alarms (ISA-18.2 states: unack, ack, rtn = returned to normal but unacknowledged, cleared) ---------- */
const at = (h, m, d = 0) => d * 86400 + h * 3600 + m * 60;
const valAt = (tag, s) => TAGS[tag].f(s);
const ALARMS = [
  { p: 1, tag: 'CP-11', title: 'Quayside critical point', t: at(2, 7), state: 'unack', live: (v) => `Pressure LOW, now ${fmt(v, 2)} bar · min 1.50` },
  { p: 3, tag: 'PRV11-PT', title: 'PRV-11 outlet', t: at(2, 9), state: 'unack', live: (v) => `Pressure LOW, now ${fmt(v, 2)} bar · limit 2.50` },
  { p: 2, tag: 'FM-11', title: 'DMA 11 inlet flow', t: at(2, 11), state: 'unack', live: (v) => `Night flow HIGH, now ${fmt(v, 1)} l/s · limit ${fmt(TAGS['FM-11'].lim[1], 1)}` },
  { p: 2, tag: 'PS1-PT', title: 'PS1 duty pump P2', t: at(3, 22), state: 'ack', ackT: at(3, 25), ackBy: 'IC', msg: 'Tripped on motor overload · standby P3 running' },
  { p: 4, tag: 'CP-07', title: 'CP-07 pressure logger', t: at(3, 31), state: 'ack', ackT: at(3, 36), ackBy: 'IC', live: () => `No report for ${Math.floor((now - COMMS) / 60)} min · last ${fmt(TAGS['CP-07'].ser.filter((x) => x != null).pop(), 2)} bar` },
  { p: 3, tag: 'PRV04-PT', title: 'PRV-04 outlet', t: at(3, 44), state: 'rtn', rtnT: at(3, 58), msg: `Pressure HIGH, peak ${fmt(valAt('PRV04-PT', at(3, 49)), 2)} bar · limit 3.80` }
];
const HIST = [
  [-1, 5, 12, 4, 'CP-09', 'CP-09 pressure logger', 'Battery low, 12 % · replace within 7 days', 5, 20, 'IC', 7, 40],
  [-1, 7, 41, 3, 'CP-12', 'Harrow Heights critical point', `Pressure LOW ${fmt(valAt('CP-12', at(7, 40, -1)), 2)} bar · min 1.50`, 7, 44, 'DK', 8, 6],
  [-1, 7, 52, 3, 'BS12-PT', 'BS-12 booster pump 2', 'Failed to start on demand · pump 1 carried load', 7, 55, 'DK', 8, 30],
  [-1, 9, 15, 4, 'PRV09-PT', 'PRV-09 actuator', 'Position feedback mismatch, 4 %', 9, 31, 'DK', 10, 2],
  [-1, 12, 34, 2, 'PS1-PT', 'PS1 suction pressure', 'LOW 0.42 bar for 40 s · transient', 12, 35, 'DK', 12, 36],
  [-1, 14, 22, 4, 'FM-07', 'FM-07 inlet meter', 'Signal noisy, 3 dropouts in 10 min', 14, 40, 'DK', 15, 10],
  [-1, 18, 52, 3, 'FM-07', 'DMA 07 inlet flow', 'Rate of change HIGH, +9.6 l/s in 10 min · hydrant use reported', 18, 54, 'DK', 19, 25],
  [-1, 19, 8, 3, 'SR-LT', 'Cragg Hill SR level', 'Falling 0.21 m/h for 30 min', 19, 12, 'DK', 20, 5],
  [-1, 21, 40, 4, 'SR-LT', 'Cragg Hill SR hatch', 'Intrusion switch open · planned inspection', 21, 41, 'IC', 22, 12],
  [-1, 23, 2, 3, 'PS1-PT', 'PS1 night tariff changeover', 'Duty pump P1 failed to confirm run', 23, 4, 'IC', 23, 5]
