ALARMS.forEach((a, i) => { a.id = i + 1; });
const ALL = () => ALARMS.concat(HIST);
const msgOf = (a) => (a.live ? a.live(liveVal(a.tag)) : a.msg);

/* ---------- live values ---------- */
let now = NOW0;
