/* ---------- state + view switching ---------- */
const st = { view: 'net', tag: 'CP-11', range: 24, pf: { 1: true, 2: true, 3: true, 4: true }, lf: { 1: true, 2: true, 3: true, 4: true }, nsel: '11', nrange: 30, nsort: ['leak', -1], lsort: ['t', -1] };
