/* ---------- glyphs: priority is coded by shape and number as well as colour ---------- */
const GL = { 1: '<path class="dbt-water-gs" d="M9 .8 17.2 9 9 17.2.8 9z"/>', 2: '<rect class="dbt-water-gs" x="1.8" y="1.8" width="14.4" height="14.4" rx="1.6"/>', 3: '<path class="dbt-water-gs" d="M9 1.2 17.2 16H.8z"/>', 4: '<circle class="dbt-water-gs" cx="9" cy="9" r="7.6"/>' };
const glyphIn = (p) => `${GL[p]}<text class="dbt-water-gt" x="9" y="${p === 3 ? 14.2 : 12.4}">${p}</text>`;
const glyph = (p) => `<svg class="dbt-water-glyph" viewBox="0 0 18 18" aria-hidden="true">${glyphIn(p)}</svg>`;

