const map = $('.dbt-water-map');
const ROWS = [61, 173, 285, 397];
function aiX(T, v, w) { return ((clamp(v, T.sc[0], T.sc[1]) - T.sc[0]) / (T.sc[1] - T.sc[0])) * w; }
