/* ---------- live tick: clock + readings once a second, only while visible ---------- */
const clock = $('[data-clock]');
const showClock = () => { const s = now; clock.textContent = `${pad(Math.floor(s / 3600) % 24)}:${pad(Math.floor(s / 60) % 60)}:${pad(s % 60)}`; };
const timer = setInterval(() => {
  if (!root.isConnected) { clearInterval(timer); io.disconnect(); document.removeEventListener('visibilitychange', onVis); return; }
  if (!visible || document.hidden) return;
  now += 1; showClock(); sampleLive();
  updateMap();
  $$('.dbt-water-alarm', alist).forEach((el) => { const a = ALARMS.find((x) => x.id === +el.dataset.id); if (a && a.live) { const m = $('[data-am]', el); m.textContent = (a.state === 'rtn' ? `Back to normal ${hhmm(a.rtnT)} · ` : '') + msgOf(a); } });
  const top = ALARMS.filter((a) => a.state !== 'cleared' && unackd(a)).sort(order)[0];
  if (top && top.live) $('[data-btext]').innerHTML = `<b>${top.tag}</b>${top.title} — ${msgOf(top)} <span>· ${hhmm(top.t)}</span>`;
  if (st.view === 'net') { const T = TAGS[st.tag]; $('[data-tdesc]').textContent = `${T.desc} · now ${fmt(liveVal(T.id), T.dec)} ${T.unit}${T.stale ? ' (stale)' : ''}`; }
}, 1000);
let rw = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const w = root.clientWidth; if (w === rw) return; rw = w;
  if (st.view === 'net') drawTrend(false);
  if (st.view === 'night') drawNight(false);
  if (st.view === 'log') drawRate(false);
});
ro.observe(root);

/* ---------- mount ---------- */
showClock();
updateMap();
renderAlarms(false);
requestAnimationFrame(() => { if (!root.isConnected) return; drawTrend(true); });
